  }]]},{move_to={ -4.159154, 0.099868, -5.017212 }, json=[[{"GUID": "6a1fe4", "Name": "Custom_Tile", "Transform": {"posX": -74.7787, "posY": 1.69474232, "posZ": 30.953907, "rotX": 0.0182202309, "rotY": 179.956573, "rotZ": 0.00720545463, "scaleX": 8.82, "scaleY": 1.0, "scaleZ": 8.82}, "Nickname": "Lizard Board", "Description": "", "GMNotes": "", "ColorDiffuse": {"r": 0.905, "g": 0.898, "b": 0.1719957}, "LayoutGroupSortIndex": 0, "Value": 0, "Locked": true, "Grid": true, "Snap": true, "IgnoreFoW": false, "MeasureMovement": false, "DragSelectable": true, "Autoraise": true, "Sticky": true, "Tooltip": false, "GridProjection": false, "HideWhenFaceDown": false, "Hands": false, "CustomImage": {"ImageURL": "https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/lizard_board_v2_167c61ed.png", "ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/1807607729518169828/BF093EA9F278FAF85874FF396741D029A117A270/", "ImageScalar": 1.0, "WidthScale": 0.0, "CustomTile": {"Type": 0, "Thickness": 0.1, "Stackable": false, "Stretch": true}}, "LuaScript": "SUITS = { \"mouse\", \"rabbit\", \"fox\" }\n\nSLOT_X  = -0.73\nSLOT_Z  = { mouse = 0.0284, rabbit = 0.3749, fox = 0.7320 }\nPILE_X  = { 0.05, 0.95 }\nPILE_Z  = 0.9\n\nBOARD_SLOT = { mouse = -0.7047, rabbit = -0.8956, fox = -1.0972 }\nBOARD_SLOT_Z = -0.0551\n\nmice = 0\nbunnies = 0\nfoxes = 0\noutcast = nil\nhated = false\nwait_id = 0\n\nfunction onLoad(save_state)\n  createButtons()\n  wait_id = Wait.time(updateButtons, 1, -1)\nend\n\nfunction onDestroy()\n  Wait.stop(wait_id)\nend\n\nfunction nothing()\nend\n\nfunction addCard(suit)\n  suit = tostring(suit or \"\"):lower()\n  if string.find(suit, \"fox\", 1, true) then foxes = foxes + 1 end\n  if string.find(suit, \"mouse\", 1, true) then mice = mice + 1 end\n  if string.find(suit, \"rabbit\", 1, true) then bunnies = bunnies + 1 end\nend\n\nfunction findByName(want, objs)\n  for _, o in ipairs(objs or getAllObjects()) do\n    if (o.getName() or \"\") == want then return o end\n  end\n  return nil\nend\n\nfunction readOutcast(wiz, objs)\n  local m = findByName(\"Outcast Marker\", objs)\n  if wiz == nil or m == nil then return nil, false end\n  local ok, l = pcall(function() return wiz.positionToLocal(m.getPosition()) end)\n  if not ok or l == nil then return nil, false end\n  if math.abs(l.x - SLOT_X) > 0.35 then return nil, false end\n  local best, bestd = nil, 0.22\n  for _, suit in ipairs(SUITS) do\n    local d = math.abs(l.z - SLOT_Z[suit])\n    if d < bestd then best, bestd = suit, d end\n  end\n  return best, (m.is_face_down == true)\nend\n\nfunction countLostSouls(wiz, objs)\n  if wiz == nil then return end\n  for _, o in ipairs(objs or getAllObjects()) do\n    local t = o.tag or o.name\n    if t == \"Card\" or t == \"Deck\" then\n      local ok, l = pcall(function() return wiz.positionToLocal(o.getPosition()) end)\n      if ok and l ~= nil and l.x > PILE_X[1] and l.x < PILE_X[2] and math.abs(l.z) < PILE_Z then\n        if t == \"Card\" then\n          addCard(o.getDescription())\n        else\n          for _, c in ipairs(o.getObjects() or {}) do addCard(c.description) end\n        end\n      end\n    end\n  end\nend\n\nCOUNT_Z = 0.0834\n\nfunction createButtons()\n  for _, suit in ipairs(SUITS) do\n    self.createButton({ click_function = \"nothing\", function_owner = self, label = \"0\",\n      position = { -BOARD_SLOT[suit], 0.1, COUNT_Z }, scale = { 0.5, 0.5, 0.5 },\n      width = 0, height = 0, font_size = 120 })\n  end\nend\n\nOUTCAST_IMG = \"https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/outcast_v7_085c27c8.png\"\nHATED_IMG   = \"https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/outcast_hated_v7_d9c16b63.png\"\nSLOT_IMG    = \"https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/slot_v7_180af900.png\"\n\nPX_PER_UNIT = 100\nUI_MIRROR   = 1\nUI_Z_SIGN   = 1\nUI_SIZE     = 13.88\n\nSHOWN = nil\nUI_ASSETS_DONE = false\nUI_WARNED = false\n\nfunction uiAssetsOnce()\n  if UI_ASSETS_DONE then return end\n  UI_ASSETS_DONE = true\n  pcall(function()\n    self.UI.setCustomAssets({\n      { name = \"outcastImg\", url = OUTCAST_IMG },\n      { name = \"hatedImg\",   url = HATED_IMG },\n      { name = \"slotImg\",    url = SLOT_IMG },\n    })\n  end)\nend\n\nfunction showOutcast()\n  local want = \"none\"\n  if outcast ~= nil then want = outcast .. (hated and \"-hated\" or \"\") end\n  if want == SHOWN then return end\n  SHOWN = want\n  uiAssetsOnce()\n  local parts = {}\n  for _, suit in ipairs(SUITS) do\n    local img = \"slotImg\"\n    if suit == outcast then img = hated and \"hatedImg\" or \"outcastImg\" end\n    parts[#parts + 1] = string.format(\n      '<Image id=\\\"slot%s\\\" image=\\\"%s\\\" width=\\\"%.2f\\\" height=\\\"%.2f\\\"'\n      .. ' position=\\\"%.1f %.1f -12\\\" rotation=\\\"0 0 180\\\" raycastTarget=\\\"false\\\"/>',\n      suit, img, UI_SIZE, UI_SIZE,\n      UI_MIRROR * BOARD_SLOT[suit] * PX_PER_UNIT, UI_Z_SIGN * BOARD_SLOT_Z * PX_PER_UNIT)\n  end\n  local ok, err = pcall(function() self.UI.setXml(table.concat(parts)) end)\n  if not ok and not UI_WARNED then\n    UI_WARNED = true\n    pcall(function()\n      broadcastToAll(\"Lizard board: the outcast slots could not be drawn (\" .. tostring(err) .. \")\",\n                     { r = 1, g = 0.6, b = 0.2 })\n    end)\n  end\nend\n\nfunction updateButtons()\n  mice, bunnies, foxes = 0, 0, 0\n  outcast, hated = nil, false\n  local objs = getAllObjects()\n  local wiz = findByName(\"Lizard Wizard\", objs)\n  countLostSouls(wiz, objs)\n  outcast, hated = readOutcast(wiz, objs)\n\n  self.editButton({ index = 0, label = tostring(mice) })\n  self.editButton({ index = 1, label = tostring(bunnies) })\n  self.editButton({ index = 2, label = tostring(foxes) })\n  showOutcast()\nend", "LuaScriptState": "", "XmlUI": "", "AttachedSnapPoints": [{"Position": {"x": -0.6259084, "y": 0.100000218, "z": -0.632033467}, "Rotation": {"x": 