_BIG) > 0.01 then\n      enterObject.setScale({ x = CARD_BIG, y = 1, z = CARD_BIG })\n    end\n  end\nend\n\nfunction onObjectLeaveScriptingZone(zone, leaveObject)\n  if zone == _zone and isMoodCard(leaveObject) then\n    local s = leaveObject.getScale()\n    if s == nil or math.abs(s.x - CARD_SMALL) > 0.01 then\n      leaveObject.setScale({ x = CARD_SMALL, y = 1, z = CARD_SMALL })\n    end\n  end\nend\n\nfunction createZone()\n  local zoneName = self.getGUID() .. \" MOOD ZONE\"\n  for _, o in ipairs(getAllObjects()) do\n    if o.tag == \"Scripting\" and o.getName() == zoneName then _zone = o return end\n  end\n  _zone = spawnObject({\n    type         = \"ScriptingTrigger\",\n    position     = self.positionToWorld(PANEL_LOCAL),\n    rotation     = self.getRotation(),\n    sound        = false,\n    snap_to_grid = false,\n    scale        = ZONE_SCALE,\n  })\n  _zone.setName(zoneName)\n  pcall(function() _zone.addTag(\"RTT Faction\") end)\nend\n\nfunction resetZone()\n  if _zone == nil then return end\n  _zone.setPosition(self.positionToWorld(PANEL_LOCAL))\n  _zone.setRotation(self.getRotation())\n  _zone.setScale(ZONE_SCALE)\nend\n","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.476329625,"y": 0.199932486,"z": -0.272212625},"Rotation": {"x": -6.73067143e-06,"y": 0.04047575,"z": 2.32548859e-06}},{"Position": {"x": -0.474906,"y": 0.200149059,"z": -0.0955988},"Rotation": {"x": -9.469037e-06,"y": 0.0405303948,"z": 3.63852928e-06}},{"Position": {"x": -0.6624085,"y": 0.200423315,"z": -0.09276913},"Rotation": {"x": -7.00019064e-06,"y": 0.0402708426,"z": 2.63223228e-06}},{"Position": {"x": -0.663835645,"y": 0.200035051,"z": -0.270829767},"Rotation": {"x": -9.570433e-06,"y": 0.0403801277,"z": 3.87862246e-06}},{"Position": {"x": -0.849882364,"y": 0.2004471,"z": -0.2708915},"Rotation": {"x": -9.529719e-06,"y": 0.04040745,"z": 3.858631e-06}},{"Position": {"x": -0.8498903,"y": 0.200284988,"z": -0.09573655},"Rotation": {"x": -6.982918e-06,"y": 0.0