OBE_LOCAL) end)\n      if ok and lobe ~= nil then\n        local dx, dz = lobe.x - p.x, lobe.z - p.z\n        if dx * dx + dz * dz <= REACH * REACH then return m end\n      end\n    end\n  end\n  local best, bestd = nil, REACH * REACH\n  for _, m in ipairs(getObjectsWithTag(\"Clearing Marker\")) do\n    local ok, lobe = pcall(function() return m.positionToWorld(LOBE_LOCAL) end)\n    if ok and lobe ~= nil then\n      local dx, dz = lobe.x - p.x, lobe.z - p.z\n      local d = dx * dx + dz * dz\n      if d < bestd then best, bestd = m, d end\n    end\n  end\n  return best\nend\n\nlocal function spotOn(m, militant)\n  local target = { x = LOBE_LOCAL.x, y = LOBE_LOCAL.y, z = LOBE_LOCAL.z }\n  if not militant then\n    target.x = target.x + SIDE_LOCAL.x\n    target.z = target.z + SIDE_LOCAL.z\n  end\n  local ok, w = pcall(function() return m.positionToWorld(target) end)\n  if ok then return w end\n  return nil\nend\n\nfunction rttGlideToSpot()\n  if self.held_by_color ~= nil then return end\n  local m = markerNear(self.getPosition())\n  if m == nil then return end\n  local militant = ((self.is_face_down ~= true) == MILITANT_FACE_DOWN)\n  local w = spotOn(m, militant)\n  if w == nil then return end\n  pcall(function() HOME_GUID = m.getGUID() end)\n  local p = self.getPosition()\n  if LIFT_FROM == nil then LIFT_FROM = p.y end\n  pcall(function() self.setPositionSmooth({ w.x, LIFT_FROM + GLIDE_LIFT, w.z }, false, true) end)\n  local okr, r = pcall(function() return m.getRotation() end)\n  local okc, c = pcall(function() return self.getRotation() end)\n  if okr and r ~= nil and okc and c ~= nil then\n    local wantY = (r.y + FROG_FACING + (militant and 0 or SIDE_TILT)) % 360\n    pcall(function() self.setRotationSmooth({ c.x, wantY, (c.z + 180) % 360 }, false, true) end)\n  end\nend\n\nfunction rttPlaceOnMarker()\n  if self.held_by_color ~= nil then return end\n  local p = self.getPosition()\n  local m = markerNear(p)\n  if m == nil then HOME_GUID = nil return end\n  local militant = ((self.is_face_down == true) == MILITANT_FACE_DOWN)\n  local w = spotOn(m, militant)\n  if w == nil then return end\n  pcall(function() HOME_GUID = m.getGUID() end)\n  LIFT_FROM = nil\n  self.setPosition({ w.x, p.y, w.z })\n  local okr, r = pcall(function() return m.getRotation() end)\n  local okc, c = pcall(function() return self.getRotation() end)\n  if okr and r ~= nil and okc and c ~= nil then\n    self.setRotation({ c.x, r.y + FROG_FACING + (militant and 0 or SIDE_TILT), c.z })\n  end\nend\n\nfunction onDrop(player_color) rttPlaceOnMarker() end\n\nlocal function whenSettled(fn, tries)\n  local ready = false\n  pcall(function()\n    ready = (self.held_by_color == nil) and (self.resting ~= false)\n      and (self.isSmoothMoving ~= nil and self.isSmoothMoving() ~= true)\n  end)\n  if ready then fn() return end\n  if tries <= 0 then return end\n  Wait.time(function() whenSettled(fn, tries - 1) end, FLIP_SETTLE)\nend\n\nfunction onRotate(spin, flip, player_color, old_spin, old_flip)\n  if flip == old_flip then return end\n  pcall(rttGlideToSpot)\n  Wait.time(function() whenSettled(function() pcall(rttPlaceOnMarker) end, SETTLE_TRIES) end,\n            FLIP_SETTLE)\nend", "LuaScriptState": "", "XmlUI": ""}]]},{move_to={ -4.849718, 0.099997, 5.29008 }, json=[[{"GUID": "2c86a8","Name": "Custom_Model","Transform": {"posX": -6.836046,"posY": 35.8542328,"posZ": -45.8038139,"rotX": 0.016477447,"rotY": 179.958359,"rotZ": 0.08025028,"scaleX": 2.34,"scaleY": 2.34,"scaleZ": 2.93},"Nickname": "Diaspora Warrior","Description": "","GMNotes": "","AltLookAngle": {"x": 0.0,"y": 0.0,"z": 0.0},"ColorDiffuse": {"r": 0.6901961,"g": 0.5960784,"b": 0.0156862736},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": false,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomMesh": {"MeshURL": "https://steamusercontent-a.akamaihd