EVERYTHING['Tools']['Battle Mat'] = {color='', data={
  {move_to={ -1.134426, 0.114935, 2.640131 }, json=[[{"GUID": "2314cc","Name": "Custom_Assetbundle","Transform": {"posX": 35.64778,"posY": 37.312748,"posZ": 34.636116,"rotX": 2.00325179E-08,"rotY": 179.9886,"rotZ": -6.08890645E-08,"scaleX": 1.12499893,"scaleY": 1.12499893,"scaleZ": 1.12499893},"Nickname": "Battle Mat","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1656725692413048205/081DE665C4AA49AF85308E7647C8665BDD530923/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 0,"LoopingEffectIndex": 0},"LuaScript": "dieColorOverwrite = false\r\ndiePlayerColor = true\r\n\r\ndieType = \"Custom_Dice\"\r\n\r\ndieImage = \"https://steamusercontent-a.akamaihd.net/ugc/1750184828981645969/DC0B90D8A4EC559A72A8A2CD8EC9017863A5CFE8/\"\r\ndieSides = 12\r\n\r\nremovalDelay = 10\r\n\r\nannounce_total = true\r\nannounce_each = true\r\nannounce_player = true\r\n\r\nradialOffset = 3\r\nheightOffset = 3\r\ndieSize = 2\r\n\r\nwaitBeforeRoll = 0.5\r\n\r\ndieLimit = 2\r\n\r\nsoundEffects = false\r\n\r\nrollWatchdog = 5\r\nrollWatchdogTries = 4\r\n\r\ndieMissingNote = \"one die could not be read -- roll again\"\r\n\r\nfunction dieAlive(die)\r\n  if die == nil then return false end\r\n  local ok, dead = pcall(function() return die.isDestroyed() end)\r\n  if ok ~= true then return false end\r\n  return dead ~= true\r\nend\r\n\r\nfunction rollGuardArm()\r\n  rollGuardTries = 0\r\n  rollGuardRested = false\r\n  rollGuardNext()\r\nend\r\n\r\nfunction rollGuardNext()\r\n  Timer.destroy(\"clickRoller_guard_\"..self.getGUID())\r\n  Timer.create({\r\n    identifier=\"clickRoller_guard_\"..self.getGUID(),\r\n    function_name=\"rollGuardFire\", function_owner=self,\r\n    delay=rollWatchdog,\r\n  })\r\nend\r\n\r\nfunction rollGuardFire()\r\n  if rollInProgress ~= true then return end\r\n  local moving = false\r\n  for _, die in ipairs(currentDice or {}) do\r\n    if dieAlive(die) then\r\n      local r = true\r\n      pcall(function() r = (die.resting ~= false) end)\r\n      if not r then moving = true end\r\n    end\r\n  end\r\n  rollGuardTries = (rollGuardTries or 0) + 1\r\n  if moving then\r\n    rollGuardRested = false\r\n    if rollGuardTries <= rollWatchdogTries then rollGuardNext() return end\r\n  elseif not rollGuardRested then\r\n    rollGuardRested = true\r\n    rollGuardNext()\r\n    return\r\n  end\r\n  pcall(function() broadcastToAll(\"Battle mat: that roll never finished, so the mat has cleared itself.\",\r\n                                  {0.86, 0.72, 0.66}) end)\r\n  cleanupDice()\r\nend\r\n\r\nfunction onSave()\r\n    currentDice = currentDice or {}\r\n    if #currentDice > 0 then\r\n        local currentDiceGUIDs = {}\r\n    for _, obj in ipairs(currentDice) do\r\n        if dieAlive(obj) then\r\n    local g = nil\r\n    pcall(function() g = obj.getGUID() end)\r\n    if g ~= nil then table.insert(currentDiceGUIDs, g) end\r\n    end\r\n    end\r\n    saved_data = JSON.encode(currentDiceGUIDs)\r\n    else\r\n    saved_data = \"\"\r\n    end\r\n    return saved_data\r\nend\r\n\r\nfunction toggleSound()\r\n    local st = 'OFF'\r\n    if soundEffects then\r\n        soundEffects = false\r\n    else\r\n        soundEffects = true\r\n        st = 'ON'\r\n    end\r\n    print('Battle mat sound turned: ' .. st)\r\nend\r\n\r\nfunction onload(saved_data)\r\n    self.addContextMenuItem(\"Toggle Sound\", toggleSound)\r\n    if saved_data ~= \"\" then\r\n        local loaded_data = JSON.decode(saved_data)\r\n        for _, guid in ipairs(loaded_data) do\r\n            local obj = getObjectFromGUID(guid)\r\n            if obj ~= nil then\r\n            destroyObject(obj)\r\n            end\r\n        end\r\n        currentDice = {}\r\n    else\r\n        currentDice = {}\r\n    end\r\n\r\n    params = {\r\n        click_function = \"click_roll\",\r\n        function_owner = self,\r\n\r\n        position       = {0, 0.01, 0},\r\n        rotation       = {0, 0, 0},\r\n        width          = 4450,\r\n        height         = 4450,\r\n\r\n        color          = {0, 0, 0, 0},\r\n        tooltip        = \"Fight!\",\r\n    }\r\n    self.createButton(params)\r\n\r\n    local object, distance = self, 0.85 * self.getScale().x\r\n    local oRot = object.getRotation()\r\n\r\nfor i = 1, 10 do\r\nif i == 1 then\r\nlbl = \"X\"\r\nelse\r\nlbl = i\r\nend\r\nlocal posX = math.sin( math.rad(36*(i-1)+oRot.y) ) * distance\r\nlocal posY = 0.1\r\nlocal posZ = math.cos( math.rad(36*(i-1)+oRot.y) ) * distance\r\nlocal pos = {x=posX, y=posY, z=posZ}\r\nlocal rot = {0,180,0}\r\nlocal func = function(_,color) numberButtonPressed(i) end\r\nself.setVar(\"click_num\"..i, func)\r\nend\r\nend\r\n\r\nhitValue = 0\r\n\r\nfunction numberButtonPressed(i)\r\nfor i = 1, 10 do\r\nself.editButton({index=i, color=\"White\"})\r\nend\r\nif i == 1 or i == hitValue then\r\nhitValue = 0\r\nelse\r\nhitValue = i\r\nself.editButton({index=i, color=\"Green\"})\r\nend\r\nend\r\n\r\nfunction click_roll(_, color)\r\nlocal diceCount = 0\r\nfor _ in pairs(currentDice) do\r\ndiceCount = diceCount + 1\r\nend\r\nlocal denyRoll = false\r\nif dieLimit > 0 and diceCount >= dieLimit then\r\ndenyRoll = true\r\nend\r\nif rollInProgress == nil and denyRoll == false then\r\n\r\nlocal spawnedDie = spawnObject({\r\ntype=dieType,\r\nposition = findGlobalPosWithLocalDirection(0),\r\nrotation = randomRotation(), scale = getRelativeScale()\r\n})\r\nif dieType == \"Custom_Dice\" then\r\nspawnedDie.setCustomObject({\r\nimage = dieImage,\r\ntype = ref_customDieSides[tostring(dieSides)]\r\n})\r\nrotation_values = {\r\n    {value=0, rotation={x=27, y=0, z=72}},\r\n    {value=1, rotation={x=27, y=0, z=144}},\r\n    {value=2, rotation={x=27, y=0, z=288}},\r\n    {value=0, rotation={x=333, y=180, z=180}},\r\n    {value=3, rotation={x=90, y=180, z=0}},\r\n    {value=2, rotation={x=27, y=0, z=216}},\r\n    {value=2, rotation={x=333, y=180, z=36}},\r\n    {value=0, rotation={x=270, y=180, z=0}},\r\n    {value=3, rotation={x=27, y=0, z=0}},\r\n    {value=3, rotation={x=333, y=180, z=108}},\r\n    {value=1, rotation={x=333, y=108, z=324}},\r\n    {value=1, rotation={x=333, y=36, z=252}},\r\n}\r\nspawnedDie.setRotationValues(rotation_values)\r\nend\r\nspawnedDie.interactable = false\r\nspawnedDie.setLock(true)\r\nif dieColorOverwrite ~= false then\r\nspawnedDie.setColorTint(dieColorOverwrite)\r\nelseif diePlayerColor == true then\r\nspawnedDie.setColorTint(stringColorToRGB(color))\r\nclone_parameters = {position = findGlobalPosWithLocalDirection(0),rotation=randomRotation()}\r\nlocal spawnedDie2 = spawnedDie.clone(clone_parameters);\r\nlocal pos = findGlobalPosWithLocalDirection(-180)\r\nspawnedDie2.setPositionSmooth(pos, false, true)\r\ntable.insert(currentDice, spawnedDie)\r\ntable.insert(currentDice, spawnedDie2)\r\nend\r\n\r\nTimer.destroy(\"clickRoller_\"..self.getGUID())\r\nTimer.create({\r\nidentifier=\"clickRoller_\"..self.getGUID(), delay=waitBeforeRoll,\r\nfunction_name=\"rollDice\", function_owner=self,\r\nparameters = {color = color}\r\n})\r\nelseif rollInProgress == false then\r\ncleanupDice()\r\nclick_roll(_, color)\r\nelse\r\npcall(function() Player[color].broadcast(\"Roll in progress.\", {0.8, 0.2, 0.2}) end)\r\nend\r\nend\r\n\r\nfunction rollDice(p)\r\nrollInProgress = true\r\nrollGuardArm()\r\nlocal mine = rollSeq or 0\r\nif soundEffects then\r\n    pcall(function() self.AssetBundle.playTriggerEffect(1) end)\r\nend\r\nfunction coroutine_rollDice()\r\nfor _, die in ipairs(currentDice) do\r\nif dieAlive(die) then\r\ndie.setLock(false)\r\ndie.randomize()\r\nend\r\nwait(0.1)\r\nend\r\n\r\nmonitorDice(p.color, mine)\r\n\r\nreturn 1\r\nend\r\nstartLuaCoroutine(self, \"coroutine_rollDice\")\r\nend\r\n\r\nfunction monitorDice(color, mine)\r\nfunction coroutine_monitorDice()\r\nrepeat\r\nlocal allRest = true\r\nfor _, die in ipairs(currentDice) do\r\nif dieAlive(die) and die.resting == false then\r\nallRest = false\r\nend\r\nend\r\ncoroutine.yield(0)\r\nuntil allRest == true\r\n\r\nif mine ~= (rollSeq or 0) then return 1 end\r\n\r\nif announce_total==true or announce_each==true then\r\nif soundEffects then\r\n    pcall(function() self.AssetBundle.playTriggerEffect(0) end)\r\nend\r\npcall(function() displayResults(color) end)\r\nend\r\n\r\nwait(0.1)\r\nrollInProgress = false\r\n\r\nfor _, die in ipairs(currentDice) do\r\nif dieAlive(die) then pcall(function() die.interactable = false end) end\r\nend\r\n\r\nif removalDelay ~= -1 then\r\nTimer.destroy(\"clickRoller_cleanup_\"..self.getGUID())\r\nTimer.create({\r\nidentifier=\"clickRoller_cleanup_\"..self.getGUID(),\r\nfunction_name=\"cleanupDice\", function_owner=self,\r\ndelay=removalDelay,\r\n})\r\nend\r\n\r\nreturn 1\r\nend\r\nstartLuaCoroutine(self, \"coroutine_monitorDice\")\r\nend\r\n\r\nfunction displayResults(color)\r\nlocal total = 0\r\nlocal resultTable = {}\r\n\r\nlocal missing = 0\r\nfor _, die in ipairs(currentDice) do\r\nlocal value = nil\r\nif dieAlive(die) then pcall(function() value = die.getRotationValue() end) end\r\nif type(value) == \"number\" then\r\nif value >= hitValue then total = total + 1 end\r\ntable.insert(resultTable, value)\r\nelse\r\nmissing = missing + 1\r\nend\r\nend\r\ntable.sort(resultTable, function(a, b) return a > b end)\r\n\r\nlocal s = \"\"\r\nif announce_each == true then\r\nfor i, v in ipairs(resultTable) do\r\nif not (s == \"\"\r\n) then\r\ns = s .. \" and \"\r\nend\r\ns = s .. v\r\nif hitValue > 0 and v >= hitValue then\r\ns = s .. \"#\"\r\nend\r\nend\r\nend\r\nif hitValue > 0 and #resultTable > 0 then\r\nif s ~= \"\" then\r\ns = \"Hitting on: \" .. hitValue .. \"  |  \" .. s .. \"  |  \"\r\nend\r\nif total ~= 1 then plural = \"s.\" else plural = \".\" end\r\ns = s .. \"[b]\" .. total .. \" hit\" .. plural .. \"[/b]\"\r\nend\r\nif missing > 0 then\r\nlocal note = dieMissingNote\r\nif #resultTable == 0 then note = \"the dice could not be read -- roll again\" end\r\nif s ~= \"\" then s = s .. \"  |  \" .. note else s = note end\r\nend\r\nif announce_player == true then\r\nlocal who = nil\r\npcall(function() who = Player[color].steam_name end)\r\nif who == nil or who == \"\" then who = tostring(color) end\r\ns = who .. \"  |  \" .. s\r\nend\r\n\r\nbroadcastToAll(s, stringColorToRGB(color))\r\nend\r\n\r\nfunction cleanupDice()\r\nfor _, die in ipairs(currentDice or {}) do\r\nif dieAlive(die) then\r\npcall(function() destroyObject(die) end)\r\nend\r\nend\r\n\r\nTimer.destroy(\"clickRoller_cleanup_\"..self.getGUID())\r\nTimer.destroy(\"clickRoller_guard_\"..self.getGUID())\r\nrollInProgress = nil\r\nrollSeq = (rollSeq or 0) + 1\r\ncurrentDice = {}\r\nend\r\n\r\nfunction getRelativeScale()\r\nlocal object = self\r\nlocal matScale = object.getScale()\r\nreturn matScale * dieSize\r\nend\r\n\r\nfunction findGlobalPosWithLocalDirection(angle)\r\nlocal object, distance = self, radialOffset * self.getScale().x\r\nlocal oPos, oRot = object.getPosition(), object.getRotation()\r\nlocal posX = oPos.x + math.sin( math.rad(angle+oRot.y) ) * distance\r\nlocal posY = oPos.y + heightOffset\r\nlocal posZ = oPos.z + math.cos( math.rad(angle+oRot.y) ) * distance\r\nreturn {x=posX, y=posY, z=posZ}\r\nend\r\n\r\nfunction randomRotation()\r\nlocal u1 = math.random();\r\nlocal u2 = math.random();\r\nlocal u3 = math.random();\r\nlocal u1sqrt = math.sqrt(u1);\r\nlocal u1m1sqrt = math.sqrt(1-u1);\r\nlocal qx = u1m1sqrt *math.sin(2*math.pi*u2);\r\nlocal qy = u1m1sqrt *math.cos(2*math.pi*u2);\r\nlocal qz = u1sqrt *math.sin(2*math.pi*u3);\r\nlocal qw = u1sqrt *math.cos(2*math.pi*u3);\r\nlocal ysqr = qy * qy;\r\nlocal t0 = -2.0 * (ysqr + qz * qz) + 1.0;\r\nlocal t1 = 2.0 * (qx * qy - qw * qz);\r\nlocal t2 = -2.0 * (qx * qz + qw * qy);\r\nlocal t3 = 2.0 * (qy * qz - qw * qx);\r\nlocal t4 = -2.0 * (qx * qx + ysqr) + 1.0;\r\nif t2 > 1.0 then t2 = 1.0 end\r\nif t2 < -1.0 then ts = -1.0 end\r\nlocal xr = math.asin(t2);\r\nlocal yr = math.atan2(t3, t4);\r\nlocal zr = math.atan2(t1, t0);\r\nreturn {math.deg(xr),math.deg(yr),math.deg(zr)}\r\nend\r\n\r\nfunction wait(time)\r\nlocal start = os.time()\r\nrepeat coroutine.yield(0) until os.time() > start + time\r\nend\r\n\r\nref_customDieSides = {[\"4\"]=0, [\"6\"]=1, [\"8\"]=2, [\"10\"]=3, [\"12\"]=4, [\"20\"]=5}","LuaScriptState": "","XmlUI": ""
