EVERYTHING['Decks']['Refill Card'] = {color='', data={
  {move_to={ -0.015248, 0.214143, -5.746479 }, json=[[{"GUID": "aa1464","Name": "Custom_Token","Transform": {"posX": 92.0,"posY": 35.82524,"posZ": -56.84,"rotX": 0.01763774,"rotY": 180.0,"rotZ": 0.0801314,"scaleX": 3.38,"scaleY": 1.0,"scaleZ": 3.38},"Nickname": "","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"Tags": ["Deck Object"],"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": false,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/792008635622436482/5F66602DA4FC363CCFED7A59E8542298BC2C2D2A/","ImageSecondaryURL": "","ImageScalar": 1.0,"WidthScale": 0.0,"CustomToken": {"Thickness": 0.200000152,"MergeDistancePixels": 3.0,"StandUp": false,"Stackable": false}},"LuaScript":  "local THE_POND = \"347917\"\r\n\r\nlocal function findPond()\r\n  local byTag = nil\r\n  pcall(function() byTag = (getObjectsWithTag(\"RTT Pond\") or {})[1] end)\r\n  if byTag ~= nil then return byTag end\r\n  return getObjectFromGUID(THE_POND)\r\nend\r\nlocal LIZARD_WIZARD = \"dc029b\"\r\nlocal LIZARD_BOARD = \"6a1fe4\"\r\nlocal VULTURE_BOARD = \"b29092\"\r\n\r\nlocal thePondLoc = {0.0,1.00,-0.09}\r\nlocal vultureBoardLoc = {-0.905,1.00,0.485}\r\nlocal lizardBoardLoc = {-0.905,1.00,0.5}\r\nlocal lizardWizardLoc = {0.484,1.00,-0.01}\r\nlocal pos_discard     = {-0.957, 0.178, 0.222}\r\nlocal pos_discard_top = {-0.957, 1.00, 0.222}\r\nlocal pos_draw        = {0.957, 0.178, 0.222}\r\nlocal rot_offset = {x=0, y=0, z=180}\r\n\r\nlocal foxPosition         = {-41.88,11.69,-10.02}\r\nlocal rabbitPosition      = {-41.88,11.68, -3.39}\r\nlocal mousePosition       = {-41.88,11.68,  3.27}\r\nlocal birdPosition        = {-41.88,11.68,  9.91}\r\nlocal abominationPosition = {-41.88,11.68, 16.55}\r\n\r\nlocal function isASuitedCard(n)\r\n  return n == \"Dominance\"\r\n      or n == \"Root Tea\"\r\n      or n == \"Ambush\"\r\n      or n == \"Travel Gear\"\r\n      or n == \"Crossbow\"\r\nend\r\n\r\nlocal function isShuffleOnDiscard(n)\r\n  return n == \"Woodland Militias\"\r\n      or n == \"Council Spy\"\r\n      or n == \"Zealous Knights\"\r\n      or n == \"Rangersx\"\r\nend\r\n\r\nlocal function isDominance(cardName)\r\n  return string.match(tostring(cardName or \"\"), \"Dominance$\")\r\nend\r\n\r\nlocal function alive(o)\r\n  if o == nil then return false end\r\n  local ok, dead = pcall(function() return o.isDestroyed() end)\r\n  return ok and dead ~= true\r\nend\r\nlocal function nameOf(o)\r\n  local n = nil\r\n  pcall(function() n = o.getName() end)\r\n  return tostring(n or \"\")\r\nend\r\nlocal function descOf(o)\r\n  local d = nil\r\n  pcall(function() d = o.getDescription() end)\r\n  return tostring(d or \"\")\r\nend\r\nlocal function entryName(c)\r\n  if c.nickname ~= nil and c.nickname ~= \"\" then return tostring(c.nickname) end\r\n  return tostring(c.name or \"\")\r\nend\r\n\r\nlocal function findObjectsAtPosition(localPos)\r\n  local globalPos = localPos\r\n  local objList = Physics.cast({\r\n    origin=globalPos,\r\n    direction={0,1,0},\r\n    type=2,\r\n    size={2,2,2},\r\n    max_distance=1,\r\n    debug=false\r\n  })\r\n\r\n  local decksAndCards = {}\r\n  for _, obj in ipairs(objList) do\r\n    if obj.hit_object.tag == \"Deck\" or obj.hit_object.tag == \"Card\" then\r\n      table.insert(decksAndCards, obj.hit_object)\r\n    end\r\n  end\r\n\r\n  return decksAndCards\r\nend\r\n\r\nfunction timer_shuffle()\r\n  local discardItemList = findObjectsAtPosition(self.positionToWorld(pos_draw))\r\n  for _, obj in ipairs(discardItemList) do\r\n    if obj.tag == \"Deck\" then\r\n      obj.shuffle()\r\n    end\r\n  end\r\nend\r\n\r\nlocal function shuffleDeckLater()\r\n  Timer.destroy(\"shuffleTimer_\"..self.getGUID())\r\n  Timer.create({\r\n    identifier = \"shuffleTimer_\"..self.getGUID(),\r\n    function_name = \"timer_shuffle\",\r\n    function_owner = self,\r\n    delay = 1\r\n  })\r\nend\r\n\r\nlocal function sendCardTo(card, pos, rot)\r\n  local nearby = { x = pos.x * 0.8, y = pos.y + 5, z = pos.z * 0.8 }\r\n  card.setPosition(nearby)\r\n  card.setRotation(rot)\r\n  card.setPosition(pos)\r\nend\r\n\r\nlocal NEEDS_SHUFFLE = 2\r\nlocal MOVED_CARD = 1\r\nlocal NO_MOVE = 0\r\n\r\nlocal ARC_Y = 2.2\r\n\r\nlocal SWEEP_S = 0.7\r\n\r\nlocal inFlight = {}\r\nlocal ARC_CLEAR_S = 2.0\r\n\r\nlocal function beginFlight(card)\r\n  local g = nil\r\n  pcall(function() g = card.getGUID() end)\r\n  if g == nil then return nil end\r\n  inFlight[g] = true\r\n  pcall(function() Wait.time(function() inFlight[g] = nil end, ARC_CLEAR_S) end)\r\n  return g\r\nend\r\n\r\nlocal function endFlight(g)\r\nend\r\n\r\nlocal function stillMoving(o)\r\n  local g = nil\r\n  pcall(function() g = o.getGUID() end)\r\n  return g ~= nil and inFlight[g] == true\r\nend\r\n\r\nlocal HANDS_PER_SEAT = 2\r\nlocal function inHand(card)\r\n  local g = nil\r\n  pcall(function() g = card.getGUID() end)\r\n  if g == nil then return false end\r\n  local found = false\r\n  pcall(function()\r\n    for _, c in ipairs(getSeatedPlayers()) do\r\n      local hands = 1\r\n      pcall(function() hands = Player[c].getHandCount() or 1 end)\r\n      if hands > HANDS_PER_SEAT then hands = HANDS_PER_SEAT end\r\n      for h = 1, hands do\r\n        pcall(function()\r\n          for _, o in ipairs(Player[c].getHandObjects(h) or {}) do\r\n            if o.getGUID() == g then found = true end\r\n          end\r\n        end)\r\n      end\r\n    end\r\n  end)\r\n  return found\r\nend\r\n\r\nlocal function spentSpot()\r\n  local v = getObjectFromGUID(VULTURE_BOARD)\r\n  local p = (v ~= nil) and v.positionToWorld(vultureBoardLoc) or self.positionToWorld(pos_discard_top)\r\n  return { x = p.x, y = p.y + ARC_Y, z = p.z }\r\nend\r\n\r\nlocal function sendCardArcTo(card, pos)\r\n  local g = beginFlight(card)\r\n  local ok = pcall(function()\r\n    local held = false\r\n    pcall(function() held = (card.held_by_color ~= nil) end)\r\n    if held or inHand(card) then\r\n      card.setPosition(spentSpot())\r\n    else\r\n      local p = card.getPosition()\r\n      card.setPositionSmooth({ p.x, p.y + ARC_Y, p.z }, false, true)\r\n    end\r\n  end)\r\n  if not ok then\r\n    card.setPositionSmooth(pos, false, true)\r\n    endFlight(g)\r\n    return\r\n  end\r\n  Wait.frames(function()\r\n    if not alive(card) then endFlight(g) return end\r\n    pcall(function() card.setPositionSmooth(pos, false, true) end)\r\n    endFlight(g)\r\n  end, 3)\r\nend\r\n\r\nlocal function sendCardHome(card, thePond, isDiscard)\r\n  local description = descOf(card):lower()\r\n  local isFrog = thePond ~= nil and description == \"frog\"\r\n\r\n  if (isDiscard or isFrog) then\r\n    local name = nameOf(card)\r\n    if isShuffleOnDiscard(name) then\r\n      local rot = self.getRotation()\r\n      sendCardTo(card, self.positionToWorld(pos_draw), {\r\n        x=rot.x+rot_offset.x,\r\n        y=rot.y+rot_offset.y,\r\n        z=rot.z+rot_offset.z\r\n      })\r\n      return NEEDS_SHUFFLE\r\n      \r\n    elseif isDominance(name) then\r\n      local home = abominationPosition\r\n      if description == \"fox\" then home = foxPosition\r\n      elseif description == \"rabbit\" then home = rabbitPosition\r\n      elseif description == \"mouse\" then home = mousePosition\r\n      elseif description == \"bird\" then home = birdPosition end\r\n      sendCardArcTo(card, home)\r\n      Wait.frames(\r\n        function()\r\n            if not alive(card) then return end\r\n            card.setRotationSmooth({0,90,0})\r\n        end,\r\n        10\r\n      )\r\n      return MOVED_CARD\r\n    end\r\n  end\r\n  if isFrog then\r\n    sendCardTo(card, thePond.positionToWorld(thePondLoc), thePond.getRotation())\r\n    return MOVED_CARD\r\n  end\r\n  return NO_MOVE\r\nend\r\n\r\nlocal function sendDeckHome(item, thePond, isDiscard)\r\n  local offset = 0\r\n  local needsShuffle = false\r\n  local entries = item.getObjects()\r\n  local left = #entries\r\n  local rest = nil\r\n  for _, c in ipairs(entries) do\r\n    local cn = entryName(c)\r\n    if (isDiscard and (isShuffleOnDiscard(cn) or isDominance(cn)))\r\n        or (thePond ~= nil and tostring(c.description or \"\"):lower() == \"frog\") then\r\n      if left <= 1 then break end\r\n      local card = item.takeObject({index = c.index + offset})\r\n      offset = offset - 1\r\n      left = left - 1\r\n      if card ~= nil and sendCardHome(card, thePond, isDiscard) == NEEDS_SHUFFLE then\r\n        needsShuffle = true\r\n      end\r\n      if left <= 1 then\r\n        pcall(function() rest = item.remainder end)\r\n        break\r\n      end\r\n    end\r\n  end\r\n  if rest ~= nil and alive(rest) then\r\n    local ok, r = pcall(function() return sendCardHome(rest, thePond, isDiscard) end)\r\n    if ok and r ~= NO_MOVE then\r\n      if r == NEEDS_SHUFFLE then needsShuffle = true end\r\n      rest = nil\r\n    end\r\n  end\r\n  return needsShuffle, rest\r\nend\r\n\r\nlocal DRAW_GUARD = 2.5\r\n\r\nlocal function sendCardsAtLocationHome(location, thePond, dominance)\r\n  local items = findObjectsAtPosition(location)\r\n  local needsShuffle = false\r\n  local drawPos = nil\r\n  pcall(function() drawPos = self.positionToWorld(pos_draw) end)\r\n  for _, item in ipairs(items) do\r\n    local onDraw = false\r\n    if drawPos ~= nil then\r\n      pcall(function()\r\n        local p = item.getPosition()\r\n        onDraw = ((p.x - drawPos.x) ^ 2 + (p.z - drawPos.z) ^ 2) < DRAW_GUARD * DRAW_GUARD\r\n      end)\r\n    end\r\n    if not onDraw then\r\n    local settled = true\r\n    pcall(function() settled = (item.resting == true) and (item.held_by_color == nil)\r\n                               and not stillMoving(item) end)\r\n    if settled and item.name == \"Card\" then\r\n      if sendCardHome(item, thePond, dominance) == NEEDS_SHUFFLE then\r\n        needsShuffle = true\r\n      elseif dominance then\r\n        pcall(function()\r\n          if item.is_face_down then item.flip() end\r\n        end)\r\n      end\r\n    elseif settled and item.name == \"Deck\" then\r\n      if sendDeckHome(item, thePond, dominance) then\r\n        needsShuffle = true\r\n      end\r\n    end\r\n    end\r\n  end\r\n  return needsShuffle\r\nend\r\n\r\nlocal function sendCardSmoothTo(card, pos, rot)\r\n  pcall(function() card.setPositionSmooth(pos, false, true) end)\r\n  pcall(function() card.setRotationSmooth(rot, false, true) end)\r\nend\r\n\r\nlocal function sendPondCardHome(card, discard, discardLoc)\r\n  if isDominance(nameOf(card)) then\r\n    sendCardHome(card, nil, true)\r\n    return\r\n  end\r\n  if descOf(card):lower() ~= \"frog\" then\r\n    sendCardSmoothTo(card, discard.positionToWorld(discardLoc), discard.getRotation())\r\n  end\r\nend\r\n\r\nfunction updateButtons()\r\n  local thePond = findPond()\r\n  \r\n  local discard = self\r\n  local discardLoc = pos_discard_top\r\n  local needsShuffle = false\r\n  \r\n  local vultureBoard = getObjectFromGUID(VULTURE_BOARD)\r\n  if vultureBoard ~= nil then\r\n    discard = vultureBoard\r\n    discardLoc = vultureBoardLoc\r\n    if sendCardsAtLocationHome(vultureBoard.positionToWorld(vultureBoardLoc), thePond, true) then\r\n      needsShuffle = true\r\n    end\r\n  else\r\n    if sendCardsAtLocationHome(self.positionToWorld(pos_discard), thePond, true) then\r\n      needsShuffle = true\r\n    end\r\n  end\r\n  \r\n  if thePond ~= nil then\r\n    local lizardWizard = getObjectFromGUID(LIZARD_WIZARD)\r\n    if lizardWizard ~= nil then\r\n      discard = lizardWizard\r\n      discardLoc = lizardWizardLoc\r\n      sendCardsAtLocationHome(lizardWizard.positionToWorld(lizardWizardLoc), thePond, false)\r\n    else\r\n      lizardWizard = getObjectFromGUID(LIZARD_BOARD)\r\n      if lizardWizard ~= nil then\r\n        discard = lizardWizard\r\n        discardLoc = lizardBoardLoc\r\n        sendCardsAtLocationHome(lizardWizard.positionToWorld(lizardBoardLoc), thePond, false)\r\n      end\r\n    end\r\n    \r\n    local items = findObjectsAtPosition(thePond.positionToWorld(thePondLoc))\r\n    for _, item in ipairs(items) do\r\n      local settled = true\r\n      pcall(function() settled = (item.resting == true) and (item.held_by_color == nil)\r\n                                 and not stillMoving(item) end)\r\n      if not settled then\r\n      elseif item.name == \"Card\" then\r\n        sendPondCardHome(item, discard, discardLoc)\r\n      elseif item.name == \"Deck\" then\r\n        local offset = 0\r\n        for _, c in ipairs(item.getObjects()) do\r\n          if isDominance(entryName(c)) or tostring(c.description or \"\"):lower() ~= \"frog\" then\r\n            local card = item.takeObject({index = c.index + offset})\r\n            offset = offset - 1\r\n            sendPondCardHome(card, discard, discardLoc)\r\n          end\r\n        end\r\n      end\r\n    end\r\n  end\r\n  \r\n  if needsShuffle then\r\n    shuffleDeckLater()\r\n  end\r\nend\r\n\r\nfunction onDestroy()\r\n   Wait.stop(wait_id)\r\nend\r\n\r\nfunction onLoad()\r\n  self.createButton({\r\n    click_function=\"click_refillDeck\", function_owner=self,\r\n    position={0,0.1,-1.12}, height=200, width=620, color={1,1,1,0}\r\n  })\r\n\r\n  wait_id = Wait.time(updateButtons, SWEEP_S, -1)\r\n\r\n  addHotkey(\"Discard Hotkey\", discardHotkey)\r\nend\r\n\r\nRTT_REFILL_API = true\r\n\r\nfunction click_refillDeck()\r\n  \r\n  local pos = self.positionToWorld(pos_draw)\r\n  local rot = self.getRotation()\r\n  rot = {rot.x+rot_offset.x, rot.y+rot_offset.y, rot.z+rot_offset.z}\r\n  \r\n  local discardItemList = findObjectsAtPosition(self.positionToWorld(pos_discard))\r\n  local movedCards = #discardItemList > 0\r\n  for _, obj in ipairs(discardItemList) do\r\n      obj.setPositionSmooth(pos, false, true)\r\n      obj.setRotationSmooth(rot)\r\n  end\r\n  \r\n  local thePond = findPond()\r\n  if thePond ~= nil then\r\n    discardItemList = findObjectsAtPosition(thePond.positionToWorld(thePondLoc))\r\n    if #discardItemList > 0 then\r\n      movedCards = true\r\n      for _, obj in ipairs(discardItemList) do\r\n          obj.setPositionSmooth(pos, false, true)\r\n          obj.setRotationSmooth(rot)\r\n      end\r\n    end\r\n  end\r\n  \r\n  local vultureBoard = getObjectFromGUID(VULTURE_BOARD)\r\n  if vultureBoard ~= nil then\r\n    discardItemList = findObjectsAtPosition(vultureBoard.positionToWorld(vultureBoardLoc))\r\n    if #discardItemList > 0 then\r\n      movedCards = true\r\n      for _, obj in ipairs(discardItemList) do\r\n          obj.setPositionSmooth(pos, false, true)\r\n          obj.setRotationSmooth(rot)\r\n      end\r\n    end\r\n  end\r\n\r\n  if movedCards then\r\n    shuffleDeckLater()\r\n  end\r\nend\r\n\r\nlocal function sendDominanceHome(card)\r\n  if card.tag == 'Card' then\r\n    local ret = sendCardHome(card, nil, true)\r\n    if ret == NEEDS_SHUFFLE then\r\n      shuffleDeckLater()\r\n    end\r\n    return ret ~= NO_MOVE\r\n  elseif card.tag == 'Deck' then\r\n    local needsShuffle, rest = sendDeckHome(card, nil, true)\r\n    if needsShuffle then\r\n      shuffleDeckLater()\r\n    end\r\n    if not alive(card) then return rest == nil, rest end\r\n    return card.getQuantity() <= 0\r\n  end\r\n  return false\r\nend\r\n\r\nlocal function _discardCard(color, cardObject)\r\n  local card_list = ''\r\n  \r\n  local thePond = findPond()\r\n\r\n  if cardObject.tag == 'Card' then\r\n    card_list = nameOf(cardObject)\r\n    if isASuitedCard(card_list) then\r\n      card_list = card_list .. \" (\" .. descOf(cardObject)..\")\" \r\n    end\r\n    if sendCardHome(cardObject, thePond, false) ~= NO_MOVE then\r\n      printToAll(\"Discarded Frog Card: \"..card_list, color)\r\n      return\r\n    end\r\n  \r\n  elseif cardObject.tag == 'Deck' then\r\n    local objects = cardObject.getObjects()\r\n    local t = {}\r\n    for index, card in ipairs(objects) do\r\n      local cn = entryName(card)\r\n      table.insert(t, '| ' .. cn .. ' ')\r\n      if isASuitedCard(cn) then\r\n        table.insert(t, \" (\" .. tostring(card.description or \"\")..\") \")\r\n      end\r\n    end\r\n    card_list = table.concat(t)\r\n    \r\n    if thePond ~= nil then\r\n      local needsShuffle, rest = sendDeckHome(cardObject, thePond, false)\r\n      if needsShuffle then\r\n        shuffleDeckLater()\r\n      end\r\n      if not alive(cardObject) then\r\n        if rest == nil then\r\n          printToAll(\"Discarded Frog Cards: \"..card_list, color)\r\n          return\r\n        end\r\n        cardObject = rest\r\n      elseif cardObject.getQuantity() <= 0 then\r\n        printToAll(\"Discarded Frog Cards: \"..card_list, color)\r\n        return\r\n      end\r\n    end\r\n  end\r\n\r\n  local lizardWizard = getObjectFromGUID(LIZARD_WIZARD)\r\n  local lizardWizardPos = {}\r\n  local lizardWizardRot = {}\r\n  if (lizardWizard ~= nil) then\r\n    lizardWizardPos = lizardWizard.positionToWorld(lizardWizardLoc)\r\n    lizardWizardRot = lizardWizard.getRotation()\r\n  else\r\n    lizardWizard = getObjectFromGUID(LIZARD_BOARD)\r\n    if (lizardWizard ~= nil) then\r\n      lizardWizardPos = lizardWizard.positionToWorld(lizardBoardLoc)\r\n      lizardWizardRot = lizardWizard.getRotation()\r\n    end    \r\n  end\r\n\r\n  local discardPos = self.positionToWorld(pos_discard_top)\r\n  local discardRot = self.getRotation()\r\n\r\n  local vultureBoard = getObjectFromGUID(VULTURE_BOARD)\r\n  local vultureBoardPos = {}\r\n  local vultureBoardRot = {}\r\n  if (vultureBoard ~= nil) then\r\n    vultureBoardPos = vultureBoard.positionToWorld(vultureBoardLoc)\r\n    vultureBoardRot = vultureBoard.getRotation()\r\n  end\r\n\r\n  local cardPos = cardObject.getPosition()\r\n  local pos = {}\r\n  local rot = {}\r\n  \r\n  local atDiscard = Vector.equals(cardPos, discardPos, 1)\r\n  local atVulture = vultureBoard ~= nil and Vector.equals(cardPos, vultureBoardPos, 1)\r\n  \r\n  if lizardWizard ~= nil then\r\n    if atDiscard or atVulture or Vector.equals(cardPos, lizardWizardPos, 1) then\r\n      if vultureBoard ~= nil then\r\n        pos = vultureBoardPos\r\n        rot = vultureBoardRot\r\n        if not atVulture then\r\n          printToAll(\"Discarded Lost Souls to Warriors Wake: \"..card_list, color)\r\n        end\r\n      else\r\n        pos = discardPos\r\n        rot = discardRot\r\n        if not atDiscard then\r\n          printToAll(\"Discarded Lost Souls: \"..card_list, color)\r\n        end\r\n      end\r\n      local done, rest = sendDominanceHome(cardObject)\r\n      if done then\r\n        return\r\n      end\r\n      if rest ~= nil then cardObject = rest end\r\n    else\r\n      pos = lizardWizardPos\r\n      rot = lizardWizardRot\r\n      printToAll(\"Discarded to Lost Souls: \"..card_list, color)\r\n    end\r\n  \r\n  else\r\n    if vultureBoard ~= nil then\r\n      pos = vultureBoardPos\r\n      rot = vultureBoardRot\r\n      if not atVulture then\r\n        printToAll(\"Discarded to Warriors Wake: \"..card_list, color)\r\n      end\r\n    \r\n    else\r\n      pos = discardPos\r\n      rot = discardRot\r\n      if not atDiscard then\r\n        printToAll(\"Discarded: \"..card_list, color)\r\n      end\r\n    end\r\n    \r\n    local done, rest = sendDominanceHome(cardObject)\r\n    if done then\r\n      return\r\n    end\r\n    if rest ~= nil then cardObject = rest end\r\n  end\r\n\r\n  sendCardTo(cardObject, pos, rot)\r\nend\r\n\r\nfunction onObjectSpawn(object)\r\n  local notes = \"\"\r\n  pcall(function() notes = object.getGMNotes() or \"\" end)\r\n  if not string.match(notes, \"Quest\") then\r\n    if object.tag == 'Deck' or (object.tag == 'Card' and descOf(object) ~= '') then\r\n      object.addContextMenuItem(\r\n        'Spend/Discard',\r\n        function(playerColor) _discardCard(playerColor, object) end,\r\n        false\r\n      )\r\n    end\r\n  end\r\nend\r\n\r\nlocal DROP_RADIUS = 2.5\r\n\r\nlocal function discardWorldPos()\r\n  local v = getObjectFromGUID(VULTURE_BOARD)\r\n  if v ~= nil then return v.positionToWorld(vultureBoardLoc) end\r\n  return self.positionToWorld(pos_discard)\r\nend\r\n\r\nlocal function dropSpots()\r\n  local out = {}\r\n  local v = getObjectFromGUID(VULTURE_BOARD)\r\n  if v ~= nil then\r\n    out[#out + 1] = { pos = v.positionToWorld(vultureBoardLoc), rot = v.getRotation() }\r\n  else\r\n    out[#out + 1] = { pos = self.positionToWorld(pos_discard_top), rot = self.getRotation() }\r\n  end\r\n  local lw = getObjectFromGUID(LIZARD_WIZARD)\r\n  if lw ~= nil then\r\n    out[#out + 1] = { pos = lw.positionToWorld(lizardWizardLoc), rot = lw.getRotation(), souls = true }\r\n  else\r\n    local lb = getObjectFromGUID(LIZARD_BOARD)\r\n    if lb ~= nil then\r\n      out[#out + 1] = { pos = lb.positionToWorld(lizardBoardLoc), rot = lb.getRotation(), souls = true }\r\n    end\r\n  end\r\n  local pd = findPond()\r\n  if pd ~= nil then\r\n    out[#out + 1] = { pos = pd.positionToWorld(thePondLoc), rot = pd.getRotation(), pond = true }\r\n  end\r\n  return out\r\nend\r\n\r\nfunction onObjectDrop(player_color, obj)\r\n  if obj == nil or obj == self then return end\r\n  local kind = nil\r\n  pcall(function() kind = obj.tag end)\r\n  if kind ~= \"Card\" and kind ~= \"Deck\" then return end\r\n  local spot = nil\r\n  pcall(function()\r\n    local p = obj.getPosition()\r\n    local best = nil\r\n    for _, t in ipairs(dropSpots()) do\r\n      local d = (p.x - t.pos.x) ^ 2 + (p.z - t.pos.z) ^ 2\r\n      if d <= DROP_RADIUS * DROP_RADIUS and (best == nil or d < best) then best, spot = d, t end\r\n    end\r\n  end)\r\n  if spot == nil then return end\r\n  local moved, rest = false, nil\r\n  if not spot.souls and not spot.pond then\r\n    pcall(function() moved, rest = sendDominanceHome(obj) end)\r\n  end\r\n  if rest ~= nil then obj = rest; kind = \"Card\" end\r\n  if not alive(obj) then return end\r\n  if not moved and kind == \"Card\" then\r\n    pcall(function() if obj.is_face_down then obj.flip() end end)\r\n  end\r\n\r\n  if not moved then\r\n    local elsewhere = false\r\n    pcall(function()\r\n      elsewhere = (findPond() ~= nil) and not spot.pond\r\n                  and (descOf(obj):lower() == \"frog\")\r\n    end)\r\n    if not elsewhere then\r\n      pcall(function()\r\n        obj.setPositionSmooth(spot.pos, false, true)\r\n        obj.setRotationSmooth(spot.rot, false, true)\r\n      end)\r\n    end\r\n  end\r\nend\r\n\r\nfunction discardHotkey(player_color, hovered_object, world_position, key_down_up)\r\n  if hovered_object == nil then return end\r\n  local desc, tag = \"\", \"\"\r\n  pcall(function() desc = hovered_object.getDescription() or \"\" end)\r\n  pcall(function() tag = hovered_object.tag or \"\" end)\r\n  if string.match(desc, \"Quest\") then return end\r\n  if (tag == 'Card' and desc ~= '') or tag == 'Deck' then\r\n    _discardCard(player_color, hovered_object)\r\n  end\r\nend\r\r\n","LuaScriptState": "","XmlUI": "","PhysicsMaterial": {"StaticFriction": 0.5,"DynamicFriction": 0.5,"Bounciness": 0.0,"FrictionCombine": 0,"BounceCombine": 0},"Rigidbody": {"Mass": 1.125,"Drag": 0.1,"AngularDrag": 0.1,"UseGravity": true},"AttachedSnapPoints": [{"Position": {"x": 0.959766865,"y": 0.102499925,"z": 0.208676264},"Rotation": {"x": -2.32625879E-07,"y": 359.900146,"z": 180.0}},{"Position": {"x": -0.9572971,"y": 0.102499895,"z": 0.2228536},"Rotation": {"x": -2.22738109E-07,"y": 359.975861,"z": 180.0}}]
