function onSave()
  local ok, enc = pcall(function()
    local seats = {}
    for i, s in ipairs(RTT_SEATS or {}) do
      if s ~= nil and s.pos ~= nil then
        local boardGuid = s.boardGuid
        local board = rttLive(s.board)
        if board ~= nil then pcall(function() if board.hasTag(RTT_SELECTOR_TAG) then boardGuid = board.getGUID() end end) end
        seats[#seats + 1] = { i = i, pos = { s.pos[1], s.pos[2] }, color = s.color,
                              faction = s.faction, owner = s.owner, hand = s.hand,
                              steamId = s.steamId,
                              key = s.key, vagN = s.vagN,
                              rel = s.rel, relDone = s.relDone,
                              picker = s.picker, pickedAt = s.pickedAt, boardGuid = boardGuid }
      end
    end
    return JSON.encode({ v = 1, run = RTT_RUN_ID or 0, turnSeats = RTT_TURN_SEATS, seats = seats,
                         laid = RTT_LAID or {}, pickN = RTT_PICK_N or 0,
                         home4 = RTT_HOME_SET or {},
                         caps4 = RTT_CAP_DEALT or {},
                         dn = RTT_DN, spawned = RTT_SPAWNED or {}, started = (RTT_STARTED == true),
                         draft = { factions = RTT_DRAFT_FACTIONS or {}, taken = RTT_FAC_TAKEN or {} },
                         captains = { board = RTT_CAP_BOARD_GUID, knave = RTT_CAP_KNAVE_GUID,
                           slots = RTT_CAP_SLOT or {}, spawned = RTT_CAP_SPAWNED or {},
                           spawnN = RTT_CAP_SPAWN_N or 0, warriorN = RTT_CAP_WARRIOR_N or 0,
                           itemN = RTT_CAP_ITEM_N or 0 },
                         map = RTT_CURRENT_MAP or "",
                         marsh5p = (RTT_MARSH_5P_BUILT == true),
                         pick = RTT_TOKEN_PICK or {},
                         vpm = RTT_VP_MARKER or {},
                         order = RTT_ORDER or {},
                         suits = RTT_SUIT_MAP or {},
                         mtnCentre = RTT_MTN_CENTRE_SUIT })
  end)
  if ok then return enc end
  return ""
end

function onLoad(state)
  local recovery = nil
  RTT_CAP_DETECT_TOKEN = (RTT_CAP_DETECT_TOKEN or 0) + 1
  pcall(function()
    if type(state) ~= "string" or state == "" then return end
    local d = JSON.decode(state)
    if type(d) ~= "table" or type(d.seats) ~= "table" then return end
    RTT_SEATS = {}
    for _, e in ipairs(d.seats) do
      if type(e) == "table" and type(e.pos) == "table" then
        RTT_SEATS[#RTT_SEATS + 1] = { board = nil, pos = { e.pos[1], e.pos[2] },
                                      color = e.color, faction = e.faction,
                                      owner = e.owner, hand = e.hand,
                                      steamId = e.steamId,
                                      key = e.key, vagN = e.vagN,
                                      rel = e.rel, relDone = e.relDone,
                                      picker = e.picker, pickedAt = e.pickedAt, boardGuid = e.boardGuid }
      end
    end
    RTT_RUN_ID     = d.run or RTT_RUN_ID
    RTT_TURN_SEATS = d.turnSeats or RTT_TURN_SEATS
    local count = tonumber(d.turnSeats) or #RTT_SEATS
    RTT_DN = tonumber(d.dn) or ((count >= 1) and (count + 1) or 5)
    if type(d.spawned) == "table" then RTT_SPAWNED = d.spawned end
    RTT_DRAFT_FACTIONS = {}
    RTT_FAC_TAKEN = {}
    if type(d.draft) == "table" then
      local factions = type(d.draft.factions) == "table" and d.draft.factions or {}
      for i = 1, 6 do RTT_DRAFT_FACTIONS[i] = factions[i] or factions[tostring(i)] end
      RTT_FAC_TAKEN = d.draft.taken or {}
    end
    for _, seat in ipairs(RTT_SEATS) do
      if seat.faction ~= nil then RTT_FAC_TAKEN[seat.faction] = true end
    end
    if type(d.started) == "boolean" then RTT_STARTED = d.started end
    if type(d.captains) == "table" then
      local cap = d.captains
      RTT_CAP_BOARD_GUID, RTT_CAP_KNAVE_GUID = cap.board, cap.knave
      RTT_CAP_SLOT, RTT_CAP_SPAWNED = cap.slots or {}, cap.spawned or {}
      RTT_CAP_SPAWN_N = tonumber(cap.spawnN) or 0
      RTT_CAP_WARRIOR_N = tonumber(cap.warriorN) or 0
      RTT_CAP_ITEM_N = tonumber(cap.itemN) or 0
    end
    recovery = { legacyDraft = (type(d.draft) ~= "table"), legacyCaptains = (type(d.captains) ~= "table"),
                 legacyStarted = (type(d.started) ~= "boolean"), legacySpawned = (type(d.spawned) ~= "table") }
    if recovery.legacyStarted then RTT_STARTED = true end
    if type(d.mtnCentre) == "string" then RTT_MTN_CENTRE_SUIT = d.mtnCentre end
    if type(d.suits) == "table" then RTT_SUIT_MAP = d.suits rttPublishSuits() end
    if type(d.laid) == "table" then RTT_LAID = d.laid end
    if type(d.home4) == "table" then
      RTT_HOME_SET = {}
      for k, h in pairs(d.home4) do
        if type(h) == "table" and h.p ~= nil and type(h.n) == "string" and h.n ~= "" then
          RTT_HOME_SET[h.n] = RTT_HOME_SET[h.n] or {}
          table.insert(RTT_HOME_SET[h.n], { p = h.p, r = h.r or { 0, 0, 0 } })
        elseif type(h) == "table" and type(k) == "string" then
          RTT_HOME_SET[k] = h
        end
      end
    end
    if type(d.caps4) == "table" then RTT_CAP_DEALT = d.caps4; rttPublishDealtCaptains() end
    RTT_PICK_N = d.pickN or RTT_PICK_N
    if type(d.order) == "table" then RTT_ORDER = d.order end
    if type(d.map) == "string" and d.map ~= "" then RTT_CURRENT_MAP = d.map end
    if d.marsh5p ~= nil then RTT_MARSH_5P_BUILT = (d.marsh5p == true) end
    if type(d.pick) == "table" then RTT_TOKEN_PICK = d.pick end
    if type(d.vpm) == "table" then RTT_VP_MARKER = d.vpm end
    if #RTT_SEATS > 0 then rttPublishSeats() end
  end)
  pcall(function() rttSnapshotHand2() end)
  if recovery ~= nil then rttRecoverSession(recovery) end
  pcall(function()
    addHotkey("Move back to supply/initial position", function(color) rttGizmoHome(color) end)
    addHotkey("Move a warrior from own supply to cursor", function(color) rttGizmoTake(color) end)
    addHotkey("Move any token to cursor; set type by holding numpad 2 for 2 seconds",
              function(color, _, _, isKeyUp)
      if isKeyUp then rttKey2Up(color) else rttKey2Down(color) end
    end, true)
    addHotkey("Set warrior as a knave prisoner", function(color) rttGizmoMark(color) end)
    addHotkey("Set home of selected pieces; hold numpad 4 for 1 second",
              function(color, _, _, isKeyUp)
      if isKeyUp then rttKey4Up(color) else rttKey4Down(color) end
    end, true)
  end)

  pcall(function() Wait.time(rttHoldMapLocked, RTT_MAP_LOCK_SECS, -1) end)
  pcall(function() rttHoldPrisoners() end)
  rttArmSteamTick()

end

