function setupFactionBoards(player, value, id)
  rttBusyBegin(3)
  RTT_BUSY_WHAT = "The faction boards are being set up."
  local count = (id == "fivePlayerSetup") and 5 or 4
  rttNewGame(count, { keepDraft = true, keepMap = true })
  local token, run = RTT_BUSY_TOKEN, RTT_RUN_ID
  for i = 1, count do
    local x, z = RTT_POS[i][1], RTT_POS[i][2]
    spawnManualFactionSelector({ x, 11.56, z }, { 0, (z > 0) and 180 or 0, 0 }, true)
  end
  Wait.frames(function()
    if RTT_BUSY_TOKEN == token and RTT_RUN_ID == run then RTT_BUSY = false end
  end, 5)
end

