function rttResyncHands()
  for _, s in ipairs(RTT_SEATS or {}) do
    if s ~= nil and s.color ~= nil and s.color ~= "" and s.hand ~= nil and s.hand.pos ~= nil then
      local color, hp, hr = s.color, s.hand.pos, s.hand.rot
      pcall(function()
        local p = Player[color]
        if p == nil then return end
        local g = RTT_HAND_FIX_GROW
        local up = { position = { hp[1], hp[2], hp[3] },
                     rotation = { hr[1], hr[2], hr[3] },
                     scale = { RTT_HAND_SCALE[1] * g, RTT_HAND_SCALE[2] * g, RTT_HAND_SCALE[3] * g } }
        local home = { position = { hp[1], hp[2], hp[3] },
                       rotation = { hr[1], hr[2], hr[3] }, scale = RTT_HAND_SCALE }
        p.setHandTransform(up, 1)
        Wait.frames(function()
          pcall(function()
            local q = Player[color]
            if q ~= nil then q.setHandTransform(home, 1) end
          end)
        end, RTT_HAND_FIX_HOLD)
      end)
    end
  end
  pcall(function() if rttResyncHands2 ~= nil then rttResyncHands2() end end)
end

function rttResyncSkip()
  local skip = {}
  pcall(function() skip[self.getGUID()] = true end)
  for guid, was in pairs(RTT_LAID or {}) do
    skip[guid] = true
    if type(was) == "table" and was.disc ~= nil then skip[was.disc] = true end
  end
  for guid in pairs(RTT_MARKING or {}) do skip[guid] = true end
  pcall(function()
    for _, o in ipairs(getObjectsWithTag("Table Piece") or {}) do
      pcall(function() skip[o.getGUID()] = true end)
    end
  end)
  pcall(function()
    for _, o in ipairs(getAllObjects()) do
      if rttNameOf(o) == "Flex Table Control" then pcall(function() skip[o.getGUID()] = true end) end
    end
  end)
  pcall(function()
    for _, c in ipairs(getSeatedPlayers()) do
      local hands = 1
      pcall(function() hands = Player[c].getHandCount() or 1 end)
      if hands > RTT_HANDS_PER_SEAT then hands = RTT_HANDS_PER_SEAT end
      for h = 1, hands do
        pcall(function()
          for _, o in ipairs(Player[c].getHandObjects(h) or {}) do
            pcall(function() skip[o.getGUID()] = true end)
          end
        end)
      end
    end
  end)
  return skip
end

function rttResyncTouch(o)
  local mode = RTT_RESYNC_MODE
  if mode == "tint" then
    pcall(function()
      local c = o.getColorTint()
      local r, g, b = c.r, c.g, c.b
      local nb = b + ((b > 0.5) and -(1 / 255) or (1 / 255))
      o.setColorTint({ r = r, g = g, b = nb })
      Wait.frames(function()
        pcall(function() o.setColorTint({ r = r, g = g, b = b }) end)
      end, RTT_RESYNC_HOLD)
    end)
  elseif mode == "lock" then
    pcall(function()
      if o.tag == "Card" then return end
      local guid = o.getGUID()
      local was = (o.getLock() == true)
      local p, r = o.getPosition(), o.getRotation()
      local touchable = nil
      pcall(function()
        if o.interactable == false then touchable = false; o.interactable = true end
      end)
      o.setLock(not was)
      Wait.frames(function()
        pcall(function()
          local x = getObjectFromGUID(guid)
          if x == nil then return end
          if was then
            pcall(function() x.setVelocity({ 0, 0, 0 }) end)
            pcall(function() x.setAngularVelocity({ 0, 0, 0 }) end)
            x.setPosition({ p.x, p.y, p.z })
            x.setRotation({ r.x, r.y, r.z })
          end
          x.setLock(was)
          if touchable == false then pcall(function() x.interactable = false end) end
        end)
      end, RTT_RESYNC_HOLD)
    end)
  else
    pcall(function()
      if o.hasTag(RTT_RESYNC_TAG) then return end
      local guid = o.getGUID()
      o.addTag(RTT_RESYNC_TAG)
      Wait.frames(function()
        pcall(function()
          local x = getObjectFromGUID(guid)
          if x ~= nil then x.removeTag(RTT_RESYNC_TAG) end
        end)
      end, RTT_RESYNC_HOLD)
    end)
  end
end

