function rttCardIsScripted(script)
  local bare = ((script or ""):gsub("%s+", ""))
  return bare ~= "" and bare ~= "functiononLoad()end"
end

function rttResyncHandGuids()
  local inHand = {}
  for _, color in ipairs({ "White", "Brown", "Red", "Orange", "Yellow", "Green", "Teal",
                           "Blue", "Purple", "Pink" }) do
    local ok, count = pcall(function() return Player[color].getHandCount() end)
    if not ok or type(count) ~= "number" or count < 0 then return nil end
    for h = 1, count do
      local read, objects = pcall(function() return Player[color].getHandObjects(h) end)
      if not read or type(objects) ~= "table" then return nil end
      for _, o in ipairs(objects) do
        local live = rttLive(o)
        if live ~= nil then
          local identified, guid = pcall(function() return live.getGUID() end)
          if not identified or guid == nil or guid == "" then return nil end
          inHand[guid] = true
        end
      end
    end
  end
  return inHand
end

function rttResyncCardOK(o, skip, inHand)
  local ok = false
  pcall(function()
    if not rttResyncCardboard(o) then return end
    if o.tag ~= "Card" and o.getLock() == true then return end
    if skip[o.getGUID()] == true then return end
    inHand = inHand or rttResyncHandGuids()
    if inHand == nil or inHand[o.getGUID()] then return end
    if o.held_by_color ~= nil then return end
    if o.spawning == true then return end
    if o.isSmoothMoving() then return end
    if rttCardIsScripted(o.getLuaScript()) then return end
    local b = o.getButtons()
    if b ~= nil and #b > 0 then return end
    if o.getLock() ~= true then
      local v = o.getVelocity()
      if v ~= nil and (math.abs(v.x) + math.abs(v.y) + math.abs(v.z)) > RTT_RESYNC_CARD_STILL then return end
    end
    ok = true
  end)
  return ok
end

