function rttResyncCardSnapshot(o)
  local rec = nil
  pcall(function()
    local tg = {}
    for _, t in ipairs(o.getTags() or {}) do tg[#tg + 1] = t end
    rec = { guid = o.getGUID(), json = o.getJSON(), tags = tg, nick = o.getName() or "",
            pos = o.getPosition(), rot = o.getRotation(), scale = o.getScale(),
            lock = (o.getLock() == true) }
  end)
  if rec == nil or rec.json == nil or rec.json == "" then return nil end
  return rec
end

function rttResyncCardRestore(rec, guid, inHand)
  local o = getObjectFromGUID(guid)
  if o == nil then return end
  rttResyncSwapGuid(rec.guid, guid)
  inHand = inHand or rttResyncHandGuids()
  if inHand == nil or inHand[guid] then return end
  pcall(function()
    local tags = {}
    for i, t in ipairs(rec.tags) do tags[i] = t end
    if o.setTags ~= nil then o.setTags(tags)
    else for _, t in ipairs(tags) do if not o.hasTag(t) then o.addTag(t) end end end
  end)
  pcall(function()
    if o.held_by_color ~= nil then return end
    local r = o.getRotation()
    local dr = math.abs(((r.y - rec.rot.y + 180) % 360) - 180) + math.abs(((r.z - rec.rot.z + 180) % 360) - 180)
    if dr > 1 then o.setRotation({ rec.rot.x, rec.rot.y, rec.rot.z }) end
    if rec.scale ~= nil then
      local sc = o.getScale()
      if math.abs(sc.x - rec.scale.x) > 0.001 or math.abs(sc.z - rec.scale.z) > 0.001 then
        o.setScale({ rec.scale.x, rec.scale.y, rec.scale.z })
      end
    end
  end)
  pcall(function() if (o.getLock() == true) ~= rec.lock then o.setLock(rec.lock) end end)
  pcall(function()
    if o.held_by_color ~= nil then return end
    local p = o.getPosition()
    local dx, dy, dz = p.x - rec.pos.x, p.y - rec.pos.y, p.z - rec.pos.z
    if (dx * dx + dy * dy + dz * dz) > (RTT_RESYNC_CARD_EPS * RTT_RESYNC_CARD_EPS) then
      o.setPosition({ rec.pos.x, rec.pos.y, rec.pos.z })
      o.setRotation({ rec.rot.x, rec.rot.y, rec.rot.z })
    end
  end)
end

RTT_REVEAL_CARDS = false
RTT_REVEAL_DIRTY = {}
RTT_REVEAL_FLIGHTS = {}
RTT_REVEAL_Q = {}
RTT_REVEAL_PUMPING = false
RTT_REVEAL_PUMP_TOKEN = nil
RTT_REVEAL_SEQ = 0
RTT_REVEAL_EPOCH = 0

function rttRevealIsHand(zone)
  zone = rttLive(zone)
  if zone == nil then return false end
  local ok, hand = pcall(function() return zone.tag == "Hand" or zone.name == "HandTrigger" end)
  return ok and hand
end

function rttRevealCardOK(o)
  o = rttLive(o)
  local allowed, inHand = false, nil
  pcall(function()
    if o == nil or (o.name ~= "Card" and o.name ~= "CardCustom") then return end
    if RTT_REVEAL_CARDS ~= true or RTT_BUSY or RTT_RESYNC_BUSY or RTT_RESEATING then return end
    if o.is_face_down ~= false or o.held_by_color ~= nil or o.spawning or o.loading_custom then return end
    if o.isSmoothMoving() or rttCardIsScripted(o.getLuaScript()) then return end
    local buttons = o.getButtons()
    if buttons ~= nil and #buttons > 0 then return end
    local velocity, angular = o.getVelocity(), o.getAngularVelocity()
    if velocity == nil or angular == nil then return end
    for _, v in ipairs({ velocity, angular }) do
      if math.abs(v.x) + math.abs(v.y) + math.abs(v.z) > RTT_RESYNC_CARD_STILL then return end
    end
    inHand = rttResyncHandGuids()
    if inHand == nil or inHand[o.getGUID()] then return end
    local zones = o.getZones()
    if type(zones) ~= "table" then return end
    for _, zone in ipairs(zones) do
      zone = rttLive(zone)
      if zone == nil then return end
      local n, t = zone.name, zone.tag
      if n == "HandTrigger" or n == "FogOfWarTrigger" or n == "HiddenTrigger"
        or t == "Hand" or t == "Fog" or t == "FogOfWar" or t == "Hidden" then return end
      if n ~= "ScriptingTrigger" and n ~= "RandomizeTrigger" and t ~= "Scripting" and t ~= "Randomize" then return end
    end
    allowed = true
  end)
  return allowed, inHand
end

function rttRevealFinish(rec, snapshot, returned)
  local run, epoch, attempts, finished = rec.run, rec.epoch, 0, false
  local function expire()
    finished = true
    if RTT_REVEAL_FLIGHTS[snapshot.guid] == rec then RTT_REVEAL_FLIGHTS[snapshot.guid] = nil end
    if run == RTT_RUN_ID and epoch == RTT_REVEAL_EPOCH and RTT_REVEAL_DIRTY[snapshot.guid] == rec then RTT_REVEAL_DIRTY[snapshot.guid] = nil end
  end
  local function finish()
    if finished or run ~= RTT_RUN_ID or epoch ~= RTT_REVEAL_EPOCH then return end
    attempts = attempts + 1
    local live = rttLive(returned)
    local guid = nil
    pcall(function()
      if live ~= nil and live.spawning ~= true then
        guid = live.getGUID()
        if rttLive(getObjectFromGUID(guid)) ~= live then guid = nil end
      end
    end)
    if guid == nil or guid == "" then
      if attempts < 120 then Wait.frames(finish, 1) else expire() end
      return
    end
    finished = true
    rttResyncSwapGuid(snapshot.guid, guid)
    if RTT_REVEAL_FLIGHTS[snapshot.guid] == rec then RTT_REVEAL_FLIGHTS[snapshot.guid] = nil end
    local fresh, freshKey = nil, nil
    for key, candidate in pairs(RTT_REVEAL_DIRTY) do
      if candidate ~= rec and candidate.run == run and candidate.epoch == epoch
        and (key == snapshot.guid or key == guid or candidate.object == live or candidate.object == returned)
        and (fresh == nil or candidate.seq > fresh.seq) then fresh, freshKey = candidate, key end
    end
    if fresh ~= nil then
      local target = RTT_REVEAL_DIRTY[guid]
      if target == nil or target == rec or target.seq < fresh.seq then
        RTT_REVEAL_DIRTY[guid] = fresh
        fresh.guid, fresh.object = guid, live
      end
      if freshKey ~= guid and RTT_REVEAL_DIRTY[freshKey] == fresh then RTT_REVEAL_DIRTY[freshKey] = nil end
    end
    if RTT_REVEAL_DIRTY[snapshot.guid] == rec then RTT_REVEAL_DIRTY[snapshot.guid] = nil end
    if RTT_REVEAL_DIRTY[guid] == rec then RTT_REVEAL_DIRTY[guid] = nil end
    local nextExit = RTT_REVEAL_DIRTY[guid]
    local safe, inHand = rttRevealCardOK(live)
    if safe and not rec.cancelled and nextExit == nil then
      local unchanged = false
      pcall(function()
        local p, r, s = live.getPosition(), live.getRotation(), live.getScale()
        local dp = math.abs(p.x-snapshot.pos.x) + math.abs(p.y-snapshot.pos.y) + math.abs(p.z-snapshot.pos.z)
        local dr = 0
        for _, k in ipairs({ "x", "y", "z" }) do dr = dr + math.abs(((r[k]-snapshot.rot[k]+180)%360)-180) end
        local ds = math.abs(s.x-snapshot.scale.x) + math.abs(s.y-snapshot.scale.y) + math.abs(s.z-snapshot.scale.z)
        local tags = live.getTags() or {}
        local sameTags = #tags == 0
        if #tags == #snapshot.tags then
          sameTags = true
          for _, tag in ipairs(tags) do
            local found = false
            for _, old in ipairs(snapshot.tags) do if tag == old then found = true end end
            if not found then sameTags = false end
          end
        end
        unchanged = dp <= RTT_RESYNC_CARD_EPS and dr <= 1 and ds <= 0.003 and sameTags
          and (live.getLock() == true) == snapshot.lock and live.getName() == snapshot.nick
      end)
      if unchanged then rttResyncCardRestore(snapshot, guid, inHand) end
    end
    if nextExit ~= nil and nextExit ~= rec then rttRevealRequest(live) end
  end
  Wait.frames(finish, 2)
  Wait.time(expire, 2)
end

function rttRevealPump(run, token)
  if RTT_REVEAL_PUMP_TOKEN ~= token then return end
  if run ~= RTT_RUN_ID or token.epoch ~= RTT_REVEAL_EPOCH then
    RTT_REVEAL_Q, RTT_REVEAL_PUMPING, RTT_REVEAL_PUMP_TOKEN = {}, false, nil
    return
  end
  local work = table.remove(RTT_REVEAL_Q, 1)
  if work ~= nil then
    local rec = work.rec
    if RTT_REVEAL_DIRTY[rec.guid] == rec and rec.run == run and rec.ticket == work.ticket then
      local o = rttLive(rec.object)
      local predecessor = false
      for _, flight in pairs(RTT_REVEAL_FLIGHTS) do
        if flight ~= rec and flight.returned == o then predecessor = true end
      end
      if o == nil then RTT_REVEAL_DIRTY[rec.guid] = nil
      elseif not predecessor and rttRevealCardOK(o) then
        rec.queued, rec.ticket, rec.state = false, nil, "reloading"
        local snapshot = rttResyncCardSnapshot(o)
        if snapshot ~= nil then
          RTT_REVEAL_FLIGHTS[snapshot.guid] = rec
          Wait.time(function()
            if rec.run ~= RTT_RUN_ID or rec.epoch ~= RTT_REVEAL_EPOCH then return end
            if RTT_REVEAL_FLIGHTS[snapshot.guid] == rec then RTT_REVEAL_FLIGHTS[snapshot.guid] = nil end
            if RTT_REVEAL_DIRTY[rec.guid] ~= rec then return end
            if rec.state == "reloading" then
              if rttLive(getObjectFromGUID(rec.guid)) ~= nil then rec.state = "dirty"
              else RTT_REVEAL_DIRTY[rec.guid] = nil end
            end
          end, 2)
          local ok, returned = pcall(function() return o.reload() end)
          if ok and returned ~= nil then
            rec.returned = returned
            rttRevealFinish(rec, snapshot, returned)
          else
            if RTT_REVEAL_FLIGHTS[snapshot.guid] == rec then RTT_REVEAL_FLIGHTS[snapshot.guid] = nil end
            if getObjectFromGUID(rec.guid) ~= nil then rec.state = "dirty"
            elseif RTT_REVEAL_DIRTY[rec.guid] == rec then RTT_REVEAL_DIRTY[rec.guid] = nil end
          end
        else rec.state = "dirty" end
      elseif work.left > 1 then
        work.left = work.left - 1
        RTT_REVEAL_Q[#RTT_REVEAL_Q + 1] = work
      else rec.queued, rec.ticket = false, nil end
    end
  end
  if #RTT_REVEAL_Q > 0 then Wait.frames(function() rttRevealPump(run, token) end, 1)
  else RTT_REVEAL_PUMPING, RTT_REVEAL_PUMP_TOKEN = false, nil end
end

function rttRevealRequest(o)
  if RTT_REVEAL_CARDS ~= true then return end
  o = rttLive(o)
  if o == nil then return end
  local guid = nil
  pcall(function() if o.name == "Card" or o.name == "CardCustom" then guid = o.getGUID() end end)
  local rec = guid and RTT_REVEAL_DIRTY[guid]
  if rec == nil or rec.run ~= RTT_RUN_ID or rec.epoch ~= RTT_REVEAL_EPOCH or rec.queued or rec.state ~= "dirty" then return end
  local ticket, run = {}, RTT_RUN_ID
  local pumping = RTT_REVEAL_PUMP_TOKEN
  if pumping ~= nil and (pumping.run ~= run or pumping.epoch ~= RTT_REVEAL_EPOCH) then
    RTT_REVEAL_Q, RTT_REVEAL_PUMPING, RTT_REVEAL_PUMP_TOKEN = {}, false, nil
  end
  rec.ticket, rec.queued = ticket, true
  RTT_REVEAL_Q[#RTT_REVEAL_Q + 1] = { rec = rec, ticket = ticket, left = 120 }
  Wait.time(function()
    if run == RTT_RUN_ID and rec.ticket == ticket then rec.ticket, rec.queued = nil, false end
  end, 2)
  if not RTT_REVEAL_PUMPING then
    RTT_REVEAL_PUMPING = true
    local pumpToken = { run = run, epoch = RTT_REVEAL_EPOCH }
    RTT_REVEAL_PUMP_TOKEN = pumpToken
    Wait.frames(function() rttRevealPump(run, pumpToken) end, 2)
    Wait.time(function()
      if RTT_REVEAL_PUMP_TOKEN ~= pumpToken then return end
      for _, w in ipairs(RTT_REVEAL_Q) do
        if w.rec.ticket == w.ticket then w.rec.ticket, w.rec.queued = nil, false end
      end
      RTT_REVEAL_Q, RTT_REVEAL_PUMPING, RTT_REVEAL_PUMP_TOKEN = {}, false, nil
    end, 2)
  end
end

function rttRevealLeftHand(zone, o)
  if RTT_REVEAL_CARDS ~= true or not rttRevealIsHand(zone) then return end
  o = rttLive(o)
  if o == nil then return end
  local guid = nil
  pcall(function() if o.name == "Card" or o.name == "CardCustom" then guid = o.getGUID() end end)
  if guid == nil or guid == "" then return end
  local rec = RTT_REVEAL_DIRTY[guid]
  if rec == nil or rec.run ~= RTT_RUN_ID or rec.epoch ~= RTT_REVEAL_EPOCH or rec.object ~= o or rec.state ~= "dirty" then
    RTT_REVEAL_SEQ = RTT_REVEAL_SEQ + 1
    RTT_REVEAL_DIRTY[guid] = { guid = guid, object = o, run = RTT_RUN_ID, epoch = RTT_REVEAL_EPOCH,
                             seq = RTT_REVEAL_SEQ, state = "dirty" }
  end
  rttRevealRequest(o)
end

function rttRevealEnteredHand(zone, o)
  if not rttRevealIsHand(zone) then return end
  for guid, rec in pairs(RTT_REVEAL_DIRTY) do
    if rec.object == o or rec.returned == o then rec.cancelled = true; RTT_REVEAL_DIRTY[guid] = nil end
  end
end

function onObjectLeaveZone(zone, o) rttRevealLeftHand(zone, o) end
function onObjectEnterZone(zone, o) rttRevealEnteredHand(zone, o) end
function onObjectRotate(o, spin, flip, player_color, old_spin, old_flip) rttRevealRequest(o) end
function onObjectDestroy(o)
  pcall(function()
    local g = o.getGUID()
    if g ~= nil then RTT_LAID[g] = nil RTT_MARKING[g] = nil end
  end)
  for guid, rec in pairs(RTT_REVEAL_DIRTY) do
    if (rec.object == o or rec.returned == o) and rec.state ~= "reloading" then RTT_REVEAL_DIRTY[guid] = nil end
  end
end

function rttResyncCardsSettle(list, done, gen)
  local all, cards, held = {}, {}, false
  local inHand = rttResyncHandGuids()
  pcall(function() all = getAllObjects() end)
  for _, o in ipairs(all) do
    pcall(function()
      if rttResyncCardboard(o) then
        cards[#cards + 1] = { guid = o.getGUID(), p = o.getPosition(), taken = false }
        if o.held_by_color ~= nil then held = true end
      end
    end)
  end
  local lost = {}
  for _, rec in ipairs(list) do
    local hit = nil
    local live = rttLive(rec.new)
    if live ~= nil then
      local g = nil
      pcall(function() g = live.getGUID() end)
      if g ~= nil then
        for _, c in ipairs(cards) do
          if not c.taken and c.guid == g then hit = c break end
        end
        if hit == nil then hit = { guid = g, taken = false } end
      end
    end
    if hit == nil then
      for _, c in ipairs(cards) do
        if not c.taken and (c.guid == rec.guid or (rec.newguid ~= nil and c.guid == rec.newguid)) then
          hit = c break
        end
      end
    end
    if hit == nil and rec.new == nil then
      for _, c in ipairs(cards) do
        if not c.taken then
          local dx, dy, dz = c.p.x - rec.pos.x, c.p.y - rec.pos.y, c.p.z - rec.pos.z
          if (dx * dx + dy * dy + dz * dz) <= (RTT_RESYNC_CARD_EPS * RTT_RESYNC_CARD_EPS) then
            hit = c break
          end
        end
      end
    end
    if hit ~= nil then
      hit.taken = true
      rttResyncCardRestore(rec, hit.guid, inHand)
    elseif rec.new ~= nil then
    elseif not held then
      lost[#lost + 1] = rec
    end
  end
  if gen ~= nil and RTT_RUN_ID ~= gen then lost = {} end
  local i = 1
  local function put()
    if i > #lost then
      RTT_RESYNCING = false
      RTT_RESYNC_BUSY = false
      if done ~= nil then done(#list, #lost, false) end
      return
    end
    local rec = lost[i]
    i = i + 1
    pcall(function()
      spawnObjectJSON({
        json = rec.json,
        position = { rec.pos.x, rec.pos.y, rec.pos.z },
        rotation = { rec.rot.x, rec.rot.y, rec.rot.z },
        scale    = { rec.scale.x, rec.scale.y, rec.scale.z },
        callback_function = function(c)
          pcall(function() if rec.lock then c.setLock(true) end end)
          for _, t in ipairs(rec.tags) do
            pcall(function() if not c.hasTag(t) then c.addTag(t) end end)
          end
          pcall(function() rttResyncSwapGuid(rec.guid, c.getGUID()) end)
        end,
      })
    end)
    Wait.frames(put, 1)
  end
  put()
end

function rttResyncReloadCards(done)
  if RTT_BUSY == true then
    RTT_RESYNCING = false
    RTT_RESYNC_BUSY = false
    if done ~= nil then done(0, 0, true) end
    return
  end
  local gen = RTT_RUN_ID
  local skip = rttResyncSkip()
  local inHand = rttResyncHandGuids()
  local all, list, skipped = {}, {}, 0
  pcall(function() all = getAllObjects() end)
  for _, o in ipairs(all) do
    if inHand ~= nil and rttResyncCardOK(o, skip, inHand) then
      local g = nil
      pcall(function() g = o.getGUID() end)
      if g ~= nil then list[#list + 1] = g end
    else
      pcall(function()
        if rttResyncCardboard(o) and (o.tag == "Card" or o.getLock() ~= true)
            and inHand ~= nil and not inHand[o.getGUID()]
            and skip[o.getGUID()] ~= true then skipped = skipped + 1 end
      end)
    end
  end
  local i, done_recs = 1, {}
  local function pump()
    local currentHands = rttResyncHandGuids()
    if RTT_RUN_ID ~= gen or RTT_BUSY == true or currentHands == nil then i = #list + 1 end
    local n = 0
    while i <= #list and n < RTT_RESYNC_CARDS_PER_FRAME do
      local o = nil
      pcall(function() o = getObjectFromGUID(list[i]) end)
      if o ~= nil and rttResyncCardOK(o, skip, currentHands) then
        local rec = rttResyncCardSnapshot(o)
        if rec ~= nil then
          local new = nil
          pcall(function() new = o.reload() end)
          pcall(function() if new ~= nil then rec.newguid = new.getGUID() end end)
          rec.new = new
          done_recs[#done_recs + 1] = rec
        end
      end
      i = i + 1
      n = n + 1
    end
    if i <= #list then
      Wait.frames(pump, 1)
    else
      Wait.frames(function()
        rttResyncCardsSettle(done_recs, function(nc, lostc, waited) done(nc, lostc, waited, skipped) end, gen)
      end, RTT_RESYNC_CARD_SETTLE)
    end
  end
  pump()
end

RTT_RESYNC_ZONE = {
  ["Hand"] = true, ["HandTrigger"] = true,
  ["Fog"] = true, ["FogOfWarTrigger"] = true,
  ["Scripting"] = true, ["ScriptingTrigger"] = true,
  ["Layout"] = true, ["LayoutZone"] = true,
  ["Randomize"] = true, ["RandomizeTrigger"] = true,
}

function rttIsZone(o)
  if o == nil then return false end
  local a, b, c = nil, nil, nil
  pcall(function() a = o.type end)
  pcall(function() b = o.tag end)
  pcall(function() c = o.name end)
  return RTT_RESYNC_ZONE[a or ""] == true or RTT_RESYNC_ZONE[b or ""] == true
      or RTT_RESYNC_ZONE[c or ""] == true
end

function rttResyncSweep(done, retry, withCards)
  if RTT_RESYNC_BUSY then
    if retry == true then Wait.time(function() rttResyncSweep(done, false, withCards) end, 1.0) end
    return false
  end
  RTT_RESYNC_BUSY = true
  RTT_RESYNCING = true
  RTT_RESYNC_RUN = (RTT_RESYNC_RUN or 0) + 1
  local run = RTT_RESYNC_RUN
  Wait.time(function()
    if RTT_RESYNC_RUN == run and RTT_RESYNC_BUSY then
      RTT_RESYNC_BUSY = false
      RTT_RESYNCING = false
      pcall(function() broadcastToAll("Resync: the last sweep did not finish; the button is free again.",
                                      { 0.86, 0.72, 0.66 }) end)
    end
  end, RTT_RESYNC_WATCHDOG)
  local skip = rttResyncSkip()
  local all, list = {}, {}
  pcall(function() all = getAllObjects() end)
  for _, o in ipairs(all) do
    local take, guid = false, nil
    pcall(function()
      guid = o.getGUID()
      take = (o.held_by_color == nil) and (skip[guid] ~= true) and not rttIsZone(o)
    end)
    if take and guid ~= nil then list[#list + 1] = guid end
  end
  local i, touched = 1, 0
  local function finish()
    if withCards == true and RTT_RESYNC_CARDS == true then
      rttResyncReloadCards(function(nc, lostc, waited, skipped)
        if done ~= nil then done(touched, nc, lostc, waited, skipped) end
      end)
      return
    end
    RTT_RESYNCING = false
    RTT_RESYNC_BUSY = false
    if done ~= nil then done(touched, 0, 0, false) end
  end
  local function pump()
    local from = i
    local to = math.min(i + RTT_RESYNC_PER_FRAME - 1, #list)
    i = to + 1
    if i <= #list then
      Wait.frames(pump, 1)
    else
      Wait.frames(finish, RTT_RESYNC_HOLD + 2)
    end
    for k = from, to do
      local o = nil
      pcall(function() o = getObjectFromGUID(list[k]) end)
      local ok = false
      if o ~= nil then
        pcall(function()
          ok = (o.held_by_color == nil) and (o.resting ~= false) and (o.spawning ~= true)
        end)
      end
      if ok then
        rttResyncTouch(o)
        touched = touched + 1
      end
    end
  end
  pump()
  return true
end

RTT_RESYNC_AUTO = false

function rttResyncArm()
  if RTT_RESYNC_AUTO ~= true then return end
  RTT_RESYNC_TOKEN = RTT_RESYNC_TOKEN + 1
  local tok = RTT_RESYNC_TOKEN
  for _, sec in ipairs({ 2.0, 6.0 }) do
    Wait.time(function() if RTT_RESYNC_TOKEN == tok then rttResyncSweep() end end, sec)
  end
end

