function rttResyncReseatOne(color, id, name, next)
  local p = nil
  pcall(function() p = Player[color] end)
  if p == nil or p.seated ~= true then return false end
  local same = false
  pcall(function() same = (id ~= nil and p.steam_id == id) or (id == nil and p.steam_name == name) end)
  if not same then return false end
  local seat = nil
  for _, sr in ipairs(RTT_SEATS or {}) do
    if sr ~= nil and sr.color == color and sr.hand ~= nil then seat = sr end
  end
  if seat == nil then return false end
  local function me()
    local found = nil
    pcall(function()
      for _, q in ipairs(Player.getPlayers()) do
        if (id ~= nil and q.steam_id == id) or (id == nil and q.steam_name == name) then found = q end
      end
    end)
    return found
  end
  local turnWas = nil
  pcall(function() turnWas = Turns.turn_color end)
  local lifted = rttLiftHandCards(color)
  local stepped = false
  pcall(function() p.changeColor("Grey") stepped = true end)
  if not stepped then rttDealBackCards(color, lifted) return false end
  rttWriteSeatHand(color, seat.hand, true)
  local function home()
    Wait.frames(function() rttDealBackCards(color, lifted) rttRestoreTurn(turnWas) next() end, 1)
  end
  local tries = 0
  local function back()
    tries = tries + 1
    local q = me()
    if q == nil or q.color == color then return home() end
    pcall(function() q.changeColor(color) end)
    q = me()
    if q == nil or q.color == color then return home() end
    if tries < RTT_RESEAT_TRIES then return Wait.frames(back, 1) end
    pcall(function()
      broadcastToAll(tostring(name) .. ": Resync could not put you back on " .. color ..
                     "; pick it again from the seat menu.", { 1, 0.6, 0.2 })
    end)
    home()
  end
  Wait.frames(back, RTT_REHAND_FRAMES)
  return true
end

function rttResyncReseatAll(onDone)
  RTT_RESEATING = true
  rttTurnHold(true)
  local seats = {}
  pcall(function()
    for _, q in ipairs(Player.getPlayers()) do
      if q.seated == true and q.color ~= "Grey" and q.color ~= "Black" then
        seats[#seats + 1] = { color = q.color, id = q.steam_id, name = q.steam_name }
      end
    end
  end)
  local i = 0
  local function step()
    i = i + 1
    if i > #seats then
      RTT_RESEATING = false
      Wait.frames(function() rttTurnHold(false) end, 2)
      if onDone ~= nil then onDone(#seats) end
      return
    end
    local seat = seats[i]
    local started = rttResyncReseatOne(seat.color, seat.id, seat.name, function() Wait.frames(step, 1) end)
    if not started then step() end
  end
  step()
  return #seats
end

RTT_DECK_CARD_IDS = nil
function rttDeckCardIds()
  if RTT_DECK_CARD_IDS ~= nil then return RTT_DECK_CARD_IDS end
  local ids = {}
  local function harvest(list)
    for _, v in ipairs(list or {}) do
      local j = v and v.json
      if type(j) == "string" then
        for id in string.gmatch(j, '"CardID"%s*:%s*(%d+)') do ids[tonumber(id)] = true end
      end
    end
  end
  pcall(function() for _, deck in pairs(EVERYTHING['Decks'] or {}) do harvest(deck['data']) end end)
  pcall(function() harvest(EVERYTHING['Standard']['Lilypad Diaspora']['data']) end)
  RTT_DECK_CARD_IDS = ids
  return ids
end

function rttCardCensus()
  local ids = rttDeckCardIds()
  local seen, loose = {}, {}
  for _, o in ipairs(getAllObjects()) do
    pcall(function()
      local nm = o.name
      if nm == "Card" or nm == "CardCustom" then
        if o.spawning == true or o.held_by_color ~= nil then return end
        local d = o.getData()
        local id = d and tonumber(d.CardID)
        if id ~= nil and ids[id] then
          seen[id] = (seen[id] or 0) + 1
          local y = 0
          pcall(function() y = o.getPosition().y end)
          loose[#loose + 1] = { o = o, id = id, nick = tostring(d.Nickname or ""), y = y, n = #loose + 1 }
        end
      elseif nm == "Deck" or nm == "DeckCustom" then
        local d = o.getData()
        for _, c in ipairs((d and d.ContainedObjects) or {}) do
          local id = tonumber(c.CardID)
          if id ~= nil and ids[id] then seen[id] = (seen[id] or 0) + 1 end
        end
      end
    end)
  end
  local extra = {}
  for id, n in pairs(seen) do if n > 1 then extra[id] = n - 1 end end
  local skip = {}
  pcall(function() skip = rttResyncSkip() end)
  table.sort(loose, function(a, b)
    if a.y ~= b.y then return a.y < b.y end
    return a.n < b.n
  end)
  local names = {}
  for _, e in ipairs(loose) do
    if (extra[e.id] or 0) > 0 then
      local g = nil
      pcall(function() g = e.o.getGUID() end)
      if g ~= nil and skip[g] ~= true then
        pcall(function() e.o.destruct() end)
        extra[e.id] = extra[e.id] - 1
        names[#names + 1] = e.nick
      end
    end
  end
  local left = 0
  for _, n in pairs(extra) do if n > 0 then left = left + 1 end end
  return #names, names, left
end

