function rttDupeCheck()
  RTT_DUPE_TIMER = nil
  if RTT_BUSY or RTT_RESYNC_BUSY or RTT_RESEATING then return end
  local fallen = rttFallenDeckCards()
  if #fallen == 0 then return end
  local seen = nil
  for _, o in ipairs(fallen) do
    local g, id, nick, suit = nil, nil, "", ""
    pcall(function()
      g = o.getGUID()
      local d = o.getData()
      id = d and tonumber(d.CardID)
      nick = tostring(o.getName() or "")
      suit = tostring(o.getDescription() or "")
    end)
    if g ~= nil and RTT_DUPE_WARNED[g] == nil then
      RTT_DUPE_WARNED[g] = true
      if seen == nil then seen = rttDeckIdCounts() end
      local label = (nick ~= "") and nick or "A card"
      if suit ~= "" then label = label .. " (" .. suit .. ")" end
      local msg
      if id ~= nil and (seen[id] or 0) > 1 then
        msg = "Duplicate card: " .. label .. ". The extra copy fell through the table; Resync removes it."
      else
        msg = label .. " fell through the table and is out of reach."
      end
      pcall(function() broadcastToAll(msg, { 1, 0.75, 0.3 }) end)
    end
  end
end

