RTT_DICE_RADIUS = 8

function rttStrayBattleDice(matPos)
  local out = {}
  if matPos == nil then return out end
  for _, o in ipairs(getAllObjects()) do
    local take = false
    pcall(function()
      if o.name ~= "Custom_Dice" then return end
      if o.interactable ~= false then return end
      if o.held_by_color ~= nil then return end
      if RTT_KEEP_DICE[o.getGUID()] == true then return end
      local p = o.getPosition()
      local dx, dz = p.x - matPos.x, p.z - matPos.z
      take = (dx * dx + dz * dz) <= (RTT_DICE_RADIUS * RTT_DICE_RADIUS)
    end)
    if take then out[#out + 1] = o end
  end
  return out
end

function rttBattleMatState()
  local mat = rttFixture(RTT_TAG_MAT)
  if mat == nil then return nil, false, 0, false end
  local stuck = false
  pcall(function() stuck = (mat.getVar("rollInProgress") == true) end)
  local pos = nil
  pcall(function() pos = mat.getPosition() end)
  return mat, stuck, #rttStrayBattleDice(pos), rttBattleMatStale(mat)
end

function rttResyncBattleMat()
  if RTT_RESYNC_MAT ~= true then return false, 0 end
  local mat, stuck, strays, stale = rttBattleMatState()
  if mat == nil then return false, 0, false end
  if stuck ~= true and strays == 0 and stale ~= true then return false, 0, false end
  local pos, old = nil, nil
  pcall(function() pos = mat.getPosition() end)
  pcall(function() old = mat.getGUID() end)
  local gone = 0
  for _, die in ipairs(rttStrayBattleDice(pos)) do
    pcall(function() die.destruct() end)
    gone = gone + 1
  end
  pcall(function() mat.destruct() end)
  Wait.frames(function()
    pcall(function() makeSpecialWithTag("Tools", "Battle Mat", 33.17, 1.55, 9.21, "Map Object") end)
    Wait.frames(function()
      for _, o in ipairs(getObjectsWithTag("Map Object")) do
        pcall(function()
          if rttNameOf(o) == "Battle Mat" then
            o.addTag(RTT_FIXTURE_TAG)
            o.addTag(RTT_TAG_MAT)
            if old ~= nil then rttSwapGuidEverywhere(old, o.getGUID()) end
          end
        end)
      end
    end, 2)
  end, 1)
  return true, gone, stale
end

function rttResyncClick(player, value, id)
  local holders = rttWhoHolds()
  if #holders > 0 then
    local who = {}
    for _, h in ipairs(holders) do who[#who + 1] = tostring(h.name) end
    pcall(function()
      broadcastToAll("Resync did not run: " .. table.concat(who, ", ") .. " is holding a piece with the "
                     .. "mouse. Everyone drop what you hold with the mouse (cards in your hand are fine) "
                     .. "and press Resync again.", { 1, 0.75, 0.3 })
    end)
    return
  end
  local ran = rttResyncSweep(function(n, nc, lostc, waited, skipped)
    local parts = { tostring(n or 0) .. " objects" }
    if (nc or 0) > 0 then parts[#parts + 1] = tostring(nc) .. " cards reloaded" end
    if RTT_BUSY ~= true then
      local seats, strays = 0, 0
      pcall(function() seats = rttResyncReseatAll(nil) end)
      pcall(function() strays = rttEvictAllStrayHands() end)
      if seats > 0 then parts[#parts + 1] = tostring(seats) .. " hand(s) re-placed" end
      if strays > 0 then parts[#parts + 1] = tostring(strays) .. " stray hand box(es) parked" end
    end
    if (lostc or 0) > 0 then parts[#parts + 1] = tostring(lostc) .. " put back" end
    local matdone, matdice, matold = false, 0, false
    pcall(function() matdone, matdice, matold = rttResyncBattleMat() end)
    if matdone then
      parts[#parts + 1] = matold and "battle mat updated" or "battle mat replaced"
      if (matdice or 0) > 0 then parts[#parts + 1] = tostring(matdice) .. " frozen dice removed" end
    end
    local msg = "Resync done: " .. table.concat(parts, "; ")
    if RTT_BUSY == true or waited == true then msg = msg .. " (hands and cards left alone while the draft is dealing)" end
    pcall(function() broadcastToAll(msg .. ".", { 0.66, 0.82, 0.86 }) end)
    Wait.frames(function()
      local gone, names, left = 0, {}, 0
      pcall(function() gone, names, left = rttCardCensus() end)
      if gone > 0 then
        pcall(function() broadcastToAll("Resync: " .. tostring(gone) .. " duplicate card(s) removed ("
                                        .. table.concat(names, ", ") .. ").", { 1, 0.75, 0.3 }) end)
      end
      if left > 0 then
        pcall(function() broadcastToAll("Resync: " .. tostring(left) .. " card(s) twice inside decks or hands, "
                                        .. "please check.", { 1, 0.75, 0.3 }) end)
      end
    end, 10)
  end, false, true)
  if ran then
    pcall(function() broadcastToAll("Resyncing...", { 0.66, 0.82, 0.86 }) end)
  end
end
