function rttSnapshotHand2()
  if RTT_HAND2_PARKED ~= nil then return end
  RTT_HAND2_PARKED = {}
  for c, pos in pairs(RTT_HAND2_HOME) do
    RTT_HAND2_PARKED[c] = { position = Vector(pos), rotation = Vector({ 0, 0, 0 }),
                            scale = Vector({ 1, 1, 1 }) }
  end
end

function rttHand2ResetPlan(keep)
  local claims, preserve = {}, {}
  for _, color in ipairs(RTT_ALL_COLORS) do
    claims[color], preserve[color] = RTT_HAND2_CLAIM[color] or 0, true
    pcall(function()
      local count = Player[color].getHandCount()
      if type(count) ~= "number" or count < 2 then return end
      local cards = Player[color].getHandObjects(2)
      if type(cards) ~= "table" then return end
      for _, card in ipairs(cards) do
        card = rttLive(card)
        if card ~= nil then
          if keep ~= nil and keep[card.getGUID()] then return end
          local removed = false
          for _, tag in ipairs(RTT_TEARDOWN_TAGS) do if card.hasTag(tag) then removed = true end end
          if not removed then return end
        end
      end
      preserve[color] = false
    end)
  end
  return claims, preserve
end

function rttResetHands2(claims, preserve)
  rttSnapshotHand2()
  for c, t in pairs(RTT_HAND2_PARKED) do
    if (preserve == nil or preserve[c] ~= true)
      and (claims == nil or claims[c] == (RTT_HAND2_CLAIM[c] or 0)) then
      pcall(function()
        local count = Player[c].getHandCount()
        if type(count) ~= "number" or count < 2 then return end
        local cards = Player[c].getHandObjects(2)
        if type(cards) ~= "table" or #cards > 0 then return end
        Player[c].setHandTransform(t, 2)
      end)
    end
  end
end
