function rttDraftObjects()
  local keep, guids = {}, {}
  local function add(object)
    object = rttLive(object)
    if object == nil then return end
    if object.tag ~= "Card" and object.tag ~= "Deck" and object.name ~= "Card"
       and object.name ~= "CardCustom" and object.name ~= "Deck" and object.name ~= "DeckCustom" then return end
    local guid = object.getGUID()
    if not keep[guid] then keep[guid] = true; guids[#guids + 1] = guid end
  end
  for _, guid in ipairs(RTT_SPAWNED or {}) do add(getObjectFromGUID(guid)) end
  for _, tag in ipairs({ "RTT Draft Card", "RTT Order Card", "RTT Knave Captain" }) do
    for _, object in ipairs(getObjectsWithTag(tag)) do add(object) end
  end
  return keep, guids
end

