  if options.keepDraft then
    keep, guids = rttDraftObjects()
    draft = { factions = RTT_DRAFT_FACTIONS, order = RTT_ORDER, deck = RTT_ORDER_DECK,
              captains = (#getObjectsWithTag("RTT Knave Captain") > 0) and RTT_CAP_DEALT or {} }
  end
  rttClearGameObjects(keep)
  rttResetRunState()
  if draft ~= nil then
    RTT_SPAWNED = guids
    RTT_DRAFT_FACTIONS, RTT_ORDER, RTT_ORDER_DECK = draft.factions or {}, draft.order or {}, draft.deck
    RTT_CAP_DEALT = draft.captains or {}
    rttPublishDealtCaptains()
  end
  pcall(function() rttParkStrayHands() end)
  if seats ~= nil then RTT_DN = seats + 1 end
  Wait.frames(function()
    if not options.keepMap then pcall(function() rttFixMarshVariant() end) end
    pcall(function() Global.setVar("RTT_BOXSCORE_MIN", (RTT_DN or 5) - 1) end)
    pcall(function() rttSpawnMapExtras() end)
  end, 1)
  rttRemoveFrogsFromDeck()
  pcall(function() rttRemoveFrogLeftovers() end)
  if seats ~= nil then rttEnableTurns(seats) end
end
function rttBusyBegin(sec)
  RTT_BUSY = true
  RTT_BUSY_TOKEN = RTT_BUSY_TOKEN + 1
  local t = RTT_BUSY_TOKEN
  Wait.time(function() if RTT_BUSY_TOKEN == t then RTT_BUSY = false end end, sec or 15)
end

function rttBusyByHuman(player, what, sec)
  local byHuman = false
  pcall(function() byHuman = (player ~= nil and player ~= "" and player.color ~= nil) end)
  if not byHuman then return false end
  if RTT_BUSY then return true end
  RTT_BUSY_WHAT = what or "The table is busy -- one moment."
  rttBusyBegin(sec or RTT_BUILD_LOCK_SECS)
  return false
end

RTT_MAP_REROLLS = { ["Marsh Map"] = true, ["Mountain Map"] = true }

function rttLoseableMapItems()
  local n = 0
  for _, o in ipairs(getObjectsWithTag("Map Object")) do
    local fixture = false
    pcall(function() fixture = o.hasTag(RTT_FIXTURE_TAG) end)
    if not fixture then n = n + 1 end
  end
  return n
end

function rttMapWouldChange(d)
  local _, cur, fivep = rttMap()
  local target = d.map or d.places
  if target ~= nil and target ~= "" then
    if cur == nil or cur == "" then return rttLoseableMapItems() > 0 end
    if target ~= cur then return true end
    return RTT_MAP_REROLLS[target] == true
  end
  if cur ~= "Marsh Map" or d.wants5p == nil then return false end
  return (d.wants5p == true) ~= (fivep == true)
end

function rttWouldWipe(d)
  if d == nil then return false end
  if d.resetKits then return rttFactionKitsOnTable() end
  if d.clearsAll then return rttClearAllHasWork() end
  if d.deck ~= nil then return rttDeckOnTable() end
  if d.warn ~= nil and rttFactionsOnTable() then return true end
  return rttMapWouldChange(d)
end

