function spawnWingedMenaceExtraHand(color, hand1)
  RTT_HAND2_CLAIM[color] = (RTT_HAND2_CLAIM[color] or 0) + 1
  hand1 = hand1 or Player[color].getHandTransform(1)
  local pos = hand1.position or {}
  local rot = hand1.rotation or {}
  local angleY = rot.y or rot[2] or 0
  local posX = pos.x or pos[1] or 0
  local posZ = pos.z or pos[3] or 0

  local angle = 1.07 * 2 * math.pi/6 - (math.pi/180 * angleY)

  local offsetX = math.cos(angle) * 13.53
  local offsetZ = math.sin(angle) * 13.53

  local posy = Vector({posX + offsetX,12.56,posZ + offsetZ})
  local roty = rot

  Player[color].setHandTransform({
      position = posy,
      rotation = roty,
      scale    = {5.99, 5.4, 5.50},
  }, 2)
end

function rttSupportersTransform(hand1)
  local pos = (hand1 or {}).position or {}
  local rot = (hand1 or {}).rotation or {}
  local posX   = pos.x or pos[1] or 0
  local posZ   = pos.z or pos[3] or 0
  local angleY = rot.y or rot[2] or 0

  local angle = 2.517 - (math.pi/180 * angleY)

  local offsetX = math.cos(angle) * 14.73
  local offsetZ = math.sin(angle) * 14.73

  return {
      position = Vector({posX + offsetX, 12.56, posZ + offsetZ}),
      rotation = rot,
      scale    = {12, 5.4, 5.50},
  }
end

function rttHasHand(color)
  if type(color) ~= "string" or color == "" then return false end
  local n = 0
  pcall(function() n = tonumber(Player[color].getHandCount()) or 0 end)
  return n >= 1
end

function rttLive(o)
  if o == nil then return nil end
  local dead = false
  pcall(function() dead = (o.isDestroyed() == true) end)
  if dead then return nil end
  return o
end

RTT_LIFT_Y = 6

function rttLiftHandCards(color)
  local out = {}
  local hands = 1
  pcall(function() hands = Player[color].getHandCount() or 1 end)
  if hands > RTT_HANDS_PER_SEAT then hands = RTT_HANDS_PER_SEAT end
  for h = 1, hands do
    local cards = {}
    pcall(function() cards = Player[color].getHandObjects(h) or {} end)
    for _, c in ipairs(cards) do
      pcall(function()
        local g = c.getGUID()
        local p, r = c.getPosition(), c.getRotation()
        c.setPosition({ p.x, p.y + RTT_LIFT_Y, p.z })
        c.setRotation({ 0, r.y, 180 })
        c.setLock(true)
        out[#out + 1] = { guid = g, hand = h }
      end)
    end
  end
  return out
end

function rttDealBackCards(color, lifted)
  for _, e in ipairs(lifted or {}) do
    pcall(function()
      local c = getObjectFromGUID(e.guid)
      if c == nil then return end
      c.setLock(false)
      c.deal(1, color, e.hand)
    end)
  end
end

function rttMoveHand(color, transform, jog)
  if color == nil or color == "Grey" or color == "Black" or transform == nil then return false end
  local lifted = rttLiftHandCards(color)
  local ok = false
  rttWithColorFree(color, function()
    if jog then
      local g = RTT_HAND_FIX_GROW
      local sc = transform.scale or RTT_HAND_SCALE
      pcall(function()
        Player[color].setHandTransform({ position = transform.position, rotation = transform.rotation,
          scale = { (sc[1] or sc.x) * g, (sc[2] or sc.y) * g, (sc[3] or sc.z) * g } }, 1)
      end)
    end
    pcall(function() Player[color].setHandTransform(transform, 1); ok = true end)
  end)
  if #lifted > 0 then Wait.frames(function() rttDealBackCards(color, lifted) end, 1) end
  return ok
end

function rttPlaceSeatHands(color, hand, jog)
  if hand == nil or hand.pos == nil then return false end
  return rttMoveHand(color, { position = hand.pos, rotation = hand.rot or { 0, 0, 0 }, scale = RTT_HAND_SCALE }, jog)
end

function rttWriteSeatHand(color, hand, jog)
  if color == nil or hand == nil or hand.pos == nil then return end
  local h1 = { position = hand.pos, rotation = hand.rot or { 0, 0, 0 }, scale = RTT_HAND_SCALE }
  if jog then
    local g = RTT_HAND_FIX_GROW
    pcall(function()
      Player[color].setHandTransform({ position = h1.position, rotation = h1.rotation,
