      local newVec = Vector({0,1,0})
      newVec.x = vec.x
      newVec.y = vec.y + 10.01
      newVec.z = vec.z

      local new_pos = newVec
      new_pos.x = new_pos.x + x
      new_pos.y = new_pos.y + y
      new_pos.z = new_pos.z + z

      local new_rot = Vector({0,0,0})
      new_rot.x = new_rot.x
      new_rot.y = new_rot.y
      new_rot.z = new_rot.z

      spawnObjectJSON({
          json              = v.json,
          position          = new_pos,
          rotation          = new_rot,
          callback_function = callback
