RTT_HOLDER_GUID    = "aa1464"
RTT_HOLDER_DRAW    = {  0.957, 0.178, 0.222 }
RTT_HOLDER_DISCARD = { -0.957, 0.178, 0.222 }

RTT_DRAW_SLOT_R = 3.0

function rttFindDrawDeck()
  local holder = getObjectFromGUID(RTT_HOLDER_GUID)
  if holder ~= nil then
    local draw, disc = nil, nil
    pcall(function()
      draw = holder.positionToWorld(RTT_HOLDER_DRAW)
      disc = holder.positionToWorld(RTT_HOLDER_DISCARD)
    end)
    if draw ~= nil and disc ~= nil then
      local best, bestD = nil, nil
      local lone, loneD = nil, nil
      for _, o in ipairs(getAllObjects()) do
        local dd, xd, isDeck, isCard = nil, nil, false, false
        pcall(function()
          isDeck = (o.name == "Deck" or o.name == "DeckCustom")
          isCard = (o.name == "Card" or o.name == "CardCustom") and o.held_by_color == nil
          if isDeck or isCard then
            local p = o.getPosition()
            dd = math.sqrt((p.x - draw.x) ^ 2 + (p.z - draw.z) ^ 2)
            xd = math.sqrt((p.x - disc.x) ^ 2 + (p.z - disc.z) ^ 2)
          end
        end)
        if dd ~= nil and dd < xd and dd <= RTT_DRAW_SLOT_R then
          if isDeck then
            if bestD == nil or dd < bestD then best, bestD = o, dd end
          elseif loneD == nil or dd < loneD then lone, loneD = o, dd end
        end
      end
      if best ~= nil then return best end
      if lone ~= nil then return lone end
      return nil, "empty"
    end
  end
  local best, bestN = nil, -1
  for _, o in ipairs(getAllObjects()) do
    local n = nil
    pcall(function()
      local isDeck = (o.name == "Deck" or o.name == "DeckCustom")
      local isCard = (o.name == "Card" or o.name == "CardCustom")
      if (isDeck or isCard) and o.hasTag("Deck Object") then
        n = isDeck and o.getQuantity() or 1
      end
    end)
    if n ~= nil and n > bestN then best, bestN = o, n end
  end
  return best
end

RTT_OTTER_ROW    = "Riverfolk"
RTT_OTTER_CARD_X = -1.340
RTT_OTTER_CARD_DX = 5.862
RTT_OTTER_ROW_Z  = 11.126
RTT_OTTER_ROW_DZ = 7.8867
RTT_OTTER_CARD_Y = 0.29
RTT_OTTER_COLS   = 5
RTT_OTTER_ROWS   = 2
RTT_OTTER_TAKEN_R = 2.5

function rttOtterSlots()
  local seat = nil
  for _, st in ipairs(RTT_SEATS or {}) do
    if st.faction == "Riverfolk Company" and st.pos ~= nil then seat = st end
  end
  if seat == nil then return {} end
  local cx, cz = seat.pos[1], seat.pos[2]
  local flip = (cz > 0)
  local out = {}
  for r = 1, RTT_OTTER_ROWS do
    for c = RTT_OTTER_COLS, 1, -1 do
      local lx = RTT_OTTER_CARD_X + (c - (RTT_OTTER_COLS + 1) / 2) * RTT_OTTER_CARD_DX
      local lz = RTT_OTTER_ROW_Z + (r - 1) * RTT_OTTER_ROW_DZ
      local w = rttKitPos(cx, cz, flip, nil, { lx, RTT_OTTER_CARD_Y, lz })
      out[#out + 1] = { x = w.x, y = w.y, z = w.z, ry = flip and 0 or 180 }
    end
  end
  return out
end

RTT_OTTER_CLAIM = {}
RTT_OTTER_CLAIM_SECS = 3

function rttOtterClaim(sl)
  local key = string.format("%.2f,%.2f", sl.x, sl.z)
  RTT_OTTER_CLAIM[key] = true
  Wait.time(function() RTT_OTTER_CLAIM[key] = nil end, RTT_OTTER_CLAIM_SECS)
end

function rttOtterFreeSlot()
  local slots = rttOtterSlots()
  if #slots == 0 then return nil end
  local cards = {}
  for _, o in ipairs(getAllObjects()) do
    local kind = nil
    pcall(function() kind = o.name end)
    if kind == "Card" or kind == "CardCustom" or kind == "Deck" or kind == "DeckCustom" then
      local p = nil
      pcall(function() p = o.getPosition() end)
      if p ~= nil then cards[#cards + 1] = p end
    end
  end
  for _, sl in ipairs(slots) do
    local taken = RTT_OTTER_CLAIM[string.format("%.2f,%.2f", sl.x, sl.z)] == true
    if not taken then
      for _, p in ipairs(cards) do
        if (p.x - sl.x) ^ 2 + (p.z - sl.z) ^ 2 <= RTT_OTTER_TAKEN_R * RTT_OTTER_TAKEN_R then
          taken = true
          break
        end
      end
    end
    if not taken then return sl end
  end
  return nil
end

RTT_REFILL_DELAY = 0.7

function rttRefillAfterLastCard(who)
  Wait.time(function()
    local holder = getObjectFromGUID(RTT_HOLDER_GUID)
    if holder == nil then return end
    local api = false
    pcall(function() api = (holder.getVar("RTT_REFILL_API") == true) end)
    if not api then return end
    pcall(function() holder.call("click_refillDeck") end)
    pcall(function()
      broadcastToAll("That was the last card -- the deck is being refilled from the discard.",
                     { 0.86, 0.86, 0.66 })
    end)
  end, RTT_REFILL_DELAY)
end

function rttPondPile()
  local pond = (getObjectsWithTag("RTT Pond") or {})[1]
  if pond == nil then return nil, nil end
  local best = nil
  for _, o in ipairs(getAllObjects()) do
    local ok = false
    pcall(function()
      ok = (o.name == "Deck" or o.name == "DeckCustom" or o.name == "Card" or o.name == "CardCustom")
    end)
    if ok and o ~= pond then
      local d = nil
      pcall(function()
        local a, b = o.getPosition(), pond.getPosition()
        d = math.sqrt((a.x - b.x) ^ 2 + (a.z - b.z) ^ 2)
      end)
      if d ~= nil and d < 3.0 and (best == nil or d < best.d) then best = { o = o, d = d } end
    end
  end
  return pond, best and best.o or nil
end

function rttVPPanelIsMine(row, color)
  if row == nil or row == "" then return nil end
  local seats = RTT_SEATS or {}
  if #seats == 0 then return nil end
  local faction = nil
  pcall(function() faction = rttMyFaction(color) end)
  if faction == nil or faction == "" then return false end
  local key = nil
  for _, s in ipairs(seats) do
    if s ~= nil and s.faction == faction then
      key = s.key or rttFactionKey(s.faction)
      break
    end
  end
  if key == nil then pcall(function() key = rttFactionKey(faction) end) end
  local mine = nil
  pcall(function() mine = rttVPRow(key) end)
  if mine == nil then return false end
  return mine == row
end

function rttVPClick(args)
  args = args or {}
  local who, id, row = args.color, tostring(args.id or ""), tostring(args.row or "")
  local function say(msg) if who ~= nil and who ~= "" then printToColor(msg, who) end end

  local mine = nil
  pcall(function() mine = rttVPPanelIsMine(row, who) end)
  if mine == false then
    say("That is " .. row .. "'s panel. You can only use your own.")
    return
  end

  if (id == "vpDraw" or id == "vpPond") and not rttHasHand(who) then
    say("You have no hand at this seat to draw into.")
    return
  end

  if id == "vpPlus" or id == "vpMinus" then
    local sheet = (getObjectsWithTag("RTT BoxScore") or {})[1]
    if sheet == nil then say("There is no box score on the table to move a marker on.") return end
    local api = false
    pcall(function() api = (sheet.getVar("RTT_NUDGE_API") == true) end)
    if not api then say("This box score is from an older build; its score cannot be driven here.") return end
    local why = sheet.call("rttNudge", { row = row, delta = (id == "vpPlus") and 1 or -1 })
    if type(why) == "string" then say(why) end

  elseif id == "vpDraw" then
    local deck, why = rttFindDrawDeck()
    if deck == nil then
      say((why == "empty") and "The draw pile is empty." or "There is no draw deck on the table.")
      return
    end
    local last = false
    pcall(function() last = (deck.name == "Card" or deck.name == "CardCustom") end)
    local slot = (row == RTT_OTTER_ROW) and rttOtterFreeSlot() or nil
    local dealt = false
    if slot ~= nil then
      if last then
        pcall(function()
          deck.setPositionSmooth({ slot.x, slot.y, slot.z }, false, true)
          deck.setRotationSmooth({ 0, slot.ry, 0 }, false, true)
          dealt = true
        end)
      else
        pcall(function()
          deck.takeObject({
            position = { slot.x, slot.y, slot.z },
            rotation = { 0, slot.ry, 0 },
            smooth   = true,
          })
          dealt = true
        end)
      end
      if not dealt then say("That card would not go to the otters' board.") return end
      rttOtterClaim(slot)
    else
      if row == RTT_OTTER_ROW then
        say("The otters' open board is full; the card goes to your hand.")
      end
      pcall(function() deck.deal(1, who) dealt = true end)
      if not dealt then say("That deck would not deal -- you may have no hand at this seat.") return end
    end
    if last then rttRefillAfterLastCard(who) end

  elseif id == "vpPond" then
    local pond, pile = rttPondPile()
    if pond == nil then say("The pond is not on the table.") return end
    if pile == nil then say("The pond is empty.") return end
    local dealt = false
    pcall(function()
      if pile.name == "Deck" or pile.name == "DeckCustom" then pile.deal(1, who)
      else pile.deal(1, who) end
      dealt = true
    end)
    if not dealt then say("The pond would not give up its top card.") end
  end
end

