function rttSpawnCaptainsFor(rulesBoard)
  if RTT_CAPTAIN_BOARD_JSON == nil or rulesBoard == nil then return end
  local run = RTT_RUN_ID
  rttAfterFrames(function()
    rulesBoard = rttLive(rulesBoard)
    if rulesBoard == nil then return end
    local fp = rulesBoard.getPosition()
    local fry = rulesBoard.getRotation().y
    local ang = math.rad(fry)
    local wx = fp.x + RTT_CAP_OFF_X * math.cos(ang) + RTT_CAP_OFF_Z * math.sin(ang)
    local wz = fp.z - RTT_CAP_OFF_X * math.sin(ang) + RTT_CAP_OFF_Z * math.cos(ang)
    spawnObjectJSON({
      json = RTT_CAPTAIN_BOARD_JSON,
      position = { wx, fp.y, wz },
      rotation = { 0, fry, 0 },
      callback_function = function(board)
        pcall(function() board.addTag("RTT Faction") end)
        pcall(function() board.addTag("RTT Captains") end)
        if RTT_RUN_ID ~= run or rttLive(rulesBoard) == nil then return end
        pcall(function() board.setLock(true) end)
        pcall(function()
          local pts = {}
          for _, sp in ipairs(board.getSnapPoints() or {}) do
            pts[#pts + 1] = { position = sp.position, rotation = { 0, 0, 0 }, rotation_snap = true }
          end
          if #pts > 0 then board.setSnapPoints(pts) end
        end)
        RTT_CAP_BOARD_GUID = board.getGUID()
        RTT_CAP_KNAVE_GUID = rulesBoard.getGUID()
        pcall(function()
          local pts = {}
          for _, sp in ipairs(rulesBoard.getSnapPoints() or {}) do
            local p = sp.position
            local px, pz = (p.x or p[1] or 0), (p.z or p[3] or 0)
            local onCol, onRow = false, false
            for _, cx in ipairs(RTT_STASH_COL) do if math.abs(px - cx) < 0.02 then onCol = true end end
            for _, rz in ipairs(RTT_STASH_ROW) do if math.abs(pz - rz) < 0.02 then onRow = true end end
            if onCol and onRow then
              pts[#pts + 1] = { position = p, rotation = { 0, 0, 0 }, rotation_snap = true }
            else
              pts[#pts + 1] = { position = p, rotation = sp.rotation }
            end
          end
          if #pts > 0 then rulesBoard.setSnapPoints(pts) end
        end)
        RTT_CAP_SLOT = {}; RTT_CAP_SPAWN_N = 0; RTT_CAP_ITEM_N = 0
        RTT_CAP_SPAWNED = {}; RTT_CAP_WARRIOR_N = 0
        pcall(function() rttBuildCaptainMeeples() end)
        rttStartCaptainDetect(2.0)
      end
    })
  end, 1)
end

