function rttStartCaptainDetect(delay)
  RTT_CAP_DETECT_TOKEN = RTT_CAP_DETECT_TOKEN + 1
  local token, run = RTT_CAP_DETECT_TOKEN, RTT_RUN_ID
  Wait.time(function() if RTT_RUN_ID == run then rttCaptainDetect(token) end end, delay or 0.25)
end

function rttCaptainDetect(token)
  if token ~= nil and token ~= RTT_CAP_DETECT_TOKEN then return end
  token = token or RTT_CAP_DETECT_TOKEN
  if RTT_STARTED then return end
  local board = getObjectFromGUID(RTT_CAP_BOARD_GUID or "")
  if board == nil then return end
  if rttLive(getObjectFromGUID(RTT_CAP_KNAVE_GUID or "")) == nil then return end
  local snaps = board.getSnapPoints() or {}
  local bb = board.getBounds()
  local cards = {}
  for _, o in ipairs(getAllObjects()) do
    if o.name == "Card" or o.name == "CardCustom" then
      local p = o.getPosition()
      if math.abs(p.x - bb.center.x) <= bb.size.x / 2 + 1.5
         and math.abs(p.z - bb.center.z) <= bb.size.z / 2 + 1.5
         and math.abs(p.y - bb.center.y) <= 3.0 then
        local ok, dt = pcall(function() return o.getData() end)
        if ok and dt ~= nil and dt.CardID ~= nil and RTT_CAP_CARDID[dt.CardID] ~= nil then
          cards[#cards + 1] = { p = p, name = RTT_CAP_CARDID[dt.CardID] }
        end
      end
    end
  end
  local slots = {}
  for i, sp in ipairs(snaps) do
    local wp = board.positionToWorld(sp.position)
    local best, bd = nil, 9.0
    for _, c in ipairs(cards) do
      local d = (c.p.x - wp.x) ^ 2 + (c.p.z - wp.z) ^ 2
      if d < bd then bd = d; best = c end
    end
    local key = "slot" .. i
    if best ~= nil then
      slots[key] = best.name
      if not RTT_CAP_SPAWNED[best.name] then
        RTT_CAP_SPAWNED[best.name] = true
        rttSpawnCaptainMeeple(best.name, i - 1)
      end
    end
  end
  RTT_CAP_SLOT = slots
  rttPublishCaptains(rttCaptainList())
  local run = RTT_RUN_ID
  Wait.time(function() if RTT_RUN_ID == run then rttCaptainDetect(token) end end, 1.5)
end

function rttRecoverSession(context)
  local token, run = {}, RTT_RUN_ID
  RTT_RECOVERY_TOKEN = token
  local attempts, restored, captainsDone = 0, {}, false
  local expected = {}
  for _, seat in ipairs(RTT_SEATS or {}) do expected[seat] = seat.boardGuid end
  local function restore()
    if RTT_RECOVERY_TOKEN ~= token or RTT_RUN_ID ~= run then return end
    attempts = attempts + 1
    local pending, all = false, getAllObjects()
    local selectors = getObjectsWithTag(RTT_SELECTOR_TAG)
    for _, seat in ipairs(RTT_SEATS or {}) do
      if seat.faction == nil and not restored[seat] then
        local guid = seat.boardGuid or expected[seat]
        local board = rttLive(getObjectFromGUID(guid or ""))
        if board ~= nil and not board.hasTag(RTT_SELECTOR_TAG) then board = nil end
        if board == nil then
          for _, candidate in ipairs(selectors) do
            candidate = rttLive(candidate)
            if candidate ~= nil and rttAtSeat(candidate, seat) then board = candidate break end
          end
        end
        if board ~= nil and not board.spawning then
          rttAttachBoard(seat, board)
          local readable = true
          if context.legacyDraft then
            if board.UI.loading then pending = true; readable = false
            else
              for i = 1, 6 do
                local icon = board.UI.getAttribute("rttFac" .. i, "icon")
                if type(icon) == "string" and tableHasElement(_G['DraftableFactions'] or {}, icon) then
                  RTT_DRAFT_FACTIONS[i] = RTT_DRAFT_FACTIONS[i] or icon
                end
              end
            end
          end
          if readable and next(RTT_DRAFT_FACTIONS or {}) ~= nil then
            rttShowFactions({ seat }); restored[seat] = true
          else pending = true end
        elseif guid ~= nil or context.legacyDraft then pending = true end
      end
    end
    if context.legacySpawned then
      local tracked = {}
      for _, guid in ipairs(RTT_SPAWNED or {}) do tracked[guid] = true end
      for _, object in ipairs(all) do
        if object.hasTag("RTT Order Card") then
          local guid = object.getGUID()
          if not tracked[guid] then RTT_SPAWNED[#RTT_SPAWNED + 1] = guid; tracked[guid] = true end
        end
      end
    end
    if context.legacyStarted and token.started then
      RTT_STARTED = true
      context.legacyStarted = false
    end
    if context.legacyStarted then
      pending = true
      for _, object in ipairs(all) do
        if object.getName() == "Root Box Score" then
          pcall(function()
            local data = object.getData()
            local state = data and data.LuaScriptState
            if type(state) == "string" and state ~= "" then
              local saved = JSON.decode(state)
              if type(saved) == "table" and type(saved.started) == "boolean" then
                RTT_STARTED = saved.started; context.legacyStarted = false
                captainsDone = false
              end
            end
          end)
        end
      end
    end
    if not captainsDone then
      local board = rttLive(getObjectFromGUID(RTT_CAP_BOARD_GUID or ""))
      local knave = rttLive(getObjectFromGUID(RTT_CAP_KNAVE_GUID or ""))
      if board == nil then
        for _, object in ipairs(getObjectsWithTag("RTT Captains")) do
          object = rttLive(object)
          if object ~= nil then board = object break end
        end
      end
      if knave == nil then
        for _, object in ipairs(all) do
          if object.name == "Custom_Tile" then
            pcall(function()
              local image = (object.getCustomObject() or {}).image
              if type(image) == "string" and image:find(RTT_KNAVE_BOARD_IMG, 1, true) then knave = object end
            end)
          end
        end
      end
      if board ~= nil and knave ~= nil and not board.spawning and not knave.spawning
        and not board.loading_custom and not knave.loading_custom then
        RTT_CAP_BOARD_GUID, RTT_CAP_KNAVE_GUID = board.getGUID(), knave.getGUID()
        if context.legacyCaptains then
          local warriors = 0
          local function remember(name)
            local captain = (name or ""):match("^Captain%s*%-%s*(%a+)$")
            if captain ~= nil and RTT_CAP_ITEMS[captain] ~= nil then RTT_CAP_SPAWNED[captain] = true end
          end
          for _, object in ipairs(all) do
            remember(object.getName())
            if object.getName() == "Knaves Warrior" then warriors = warriors + 1 end
            if object.tag == "Bag" then
              pcall(function()
                for _, entry in ipairs(object.getObjects() or {}) do remember(entry.nickname or entry.name) end
              end)
            end
          end
          local count = 0
          for _ in pairs(RTT_CAP_SPAWNED) do count = count + 1 end
          RTT_CAP_SPAWN_N = math.max(RTT_CAP_SPAWN_N, count)
          RTT_CAP_WARRIOR_N = math.min(3, math.max(warriors, math.min(count, 3)))
          context.legacyCaptains = false
        end
        rttPublishCaptains(rttCaptainList())
        if not RTT_STARTED and not context.legacyStarted then rttStartCaptainDetect() end
        captainsDone = not context.legacyStarted
        if not captainsDone then pending = true end
      else
        local expected = RTT_CAP_BOARD_GUID ~= nil or RTT_CAP_KNAVE_GUID ~= nil
        for _, seat in ipairs(RTT_SEATS or {}) do
          if seat.faction == "Knaves of the Deepwood" then expected = true end
        end
        if expected then pending = true else captainsDone = true end
      end
    end
    if pending and attempts < 80 then Wait.time(restore, 0.25) end
  end
  Wait.frames(restore, 2)
end

