RTT_MONGER_LEFT  = {  25.7250, 11.562, -8.5300 }
RTT_MONGER_RIGHT = { -19.1480, 11.562, -8.5210 }

function rttSeatOffset(cx, cz, flip, rotationY, ox, oz)
  if rotationY ~= nil and rotationY ~= 0 then
    local v = Vector(ox, 0, oz)
    v:rotateOver("y", rotationY)
    return cx + v.x, cz + v.z
  end
  local s = flip and -1 or 1
  return cx + ox * s, cz + oz * s
end

function rttMongerOnPlayersRight(cx, cz)
  return (cx < 0 and cz < 0) or (cx > 0 and cz > 0)
end

function rttMoleKitDX(cx, cz)
  local dx = rttMongerOnPlayersRight(cx, cz) and -RTT_HELPER_TOWN_W or RTT_HELPER_TOWN_W
  if cx < 0 and cz > 0 then dx = dx - RTT_HELPER_TOWN_W end
  return dx
end

function rttMongerSpot(cx, cz, flip, rotationY)
  local o = rttMongerOnPlayersRight(cx, cz) and RTT_MONGER_LEFT or RTT_MONGER_RIGHT
  local x, z = rttSeatOffset(cx, cz, flip, rotationY, o[1] + rttMoleKitDX(cx, cz), o[3])
  return { x, o[2], z }
end

function rttMoleMonger(cx, cz, flip, rotationY)
  local def = EVERYTHING["Tools"] and EVERYTHING["Tools"]["Mole Monger"]
  if def == nil or def['data'] == nil or def['data'][1] == nil then return end
  local p = rttMongerSpot(cx, cz, flip, rotationY)
  spawnObjectJSON({
    json = def['data'][1].json,
    position = { p[1], p[2], p[3] },
    rotation = { 0, ((rotationY ~= nil) and (180 + rotationY) or (flip and 0 or 180)) % 360, 0 },
    callback_function = function(o)
      pcall(function() o.addTag("RTT Faction") end)
      pcall(function() o.setLock(true) end)
    end
  })
end

