      end
    end
  end
  rttSpawnStaggered(moodSpecs)
end

RTT_CAT_DROP = 13.6

RTT_CATS_TRIES = 8
RTT_CATS_WAIT  = 0.5

function rttMarquiseCats(cx, cz, flip, tries)
  tries = tries or RTT_CATS_TRIES
  local function later()
    if tries > 0 then
      rttAfterTime(function() rttMarquiseCats(cx, cz, flip, tries - 1) end, RTT_CATS_WAIT)
    end
  end
  local board, mapId, fivep = rttMap()
  local centres = (mapId ~= nil) and RTT_CLEARING_CENTRES[mapId] or nil
  if board == nil or centres == nil then
    if tries > 0 then later() return end
    pcall(function()
      broadcastToAll("Marquise: there is no map on the table, so the cats stay in the supply. "
                     .. "Place the map first.", { 1, 0.6, 0.2 })
    end)
    return
  end
  local bag = rttFindBag("Marquise Supply")
  if bag == nil then later() return end
  local excl = {}
  if mapId == "Marsh Map" then
    local is5p = fivep
    if not is5p then
      excl = RTT_MARSH_EXCLUDED
      if excl == nil then
        local mb = getObjectFromGUID("bab7e1")
        if mb ~= nil then
          local ok, ex = pcall(function() return mb.call("rttGetMarshExcluded") end)
          if ok and type(ex) == "table" then excl = ex end
        end
      end
      excl = excl or {}
    end
  end
  for _, c in ipairs(centres) do
    local skip = false
    for _, e in ipairs(excl) do
      local dx, dz = c[1] - e[1], c[2] - e[2]
      if dx * dx + dz * dz < 20.0 then skip = true break end
    end
    if not skip then
      pcall(function() bag.takeObject({ position = { c[1], RTT_CAT_DROP, c[2] }, rotation = { 0, 180, 0 },
        smooth = false,
        callback_function = function(o) pcall(function() o.addTag("RTT Faction") end) end }) end)
    end
  end
end

function rttFindSeatBoard(cx, cz)
  local board, bestD = nil, 1e9
  for _, o in ipairs(getAllObjects()) do
    if o.name == "Custom_Tile" then
      local s = o.getScale()
      if s ~= nil and s.x >= 7.5 then
        local p = o.getPosition()
        local d = (p.x - cx) ^ 2 + (p.z - cz) ^ 2
        if d < bestD and d < 900 then bestD = d; board = o end
      end
    end
  end
  return board
end

