function rttFrogCount(deck)
  local cards = deck.getObjects() or {}
  local frog = 0
  for _, c in ipairs(cards) do if (c.description or "") == "Frog" then frog = frog + 1 end end
  return frog, #cards
end

function rttFindMainDeck()
  local slot = rttFindDrawDeck()
  if slot ~= nil then
    local isDeck = false
    pcall(function() isDeck = (slot.name == "Deck" or slot.name == "DeckCustom") end)
    if isDeck then
      local frog, total = rttFrogCount(slot)
      if total > 0 and frog < total then return slot end
    end
  end
  for _, o in ipairs(getAllObjects()) do
    if o.name == "Deck" then
      local frog, total = rttFrogCount(o)
      if total >= 20 and frog < total then return o end
    end
  end
  return nil
end

function rttRemoveFrogsFromDeck()
  local deck = rttFindMainDeck()
  if deck == nil then return end
  local idx = {}
  for _, c in ipairs(deck.getObjects() or {}) do
    if (c.description or "") == "Frog" and c.index ~= nil then idx[#idx + 1] = c.index end
  end
  if #idx == 0 then return end
  table.sort(idx, function(x, y) return x > y end)
  local dp = deck.getPosition()
  local function pull(i)
    if i > #idx then return end
    pcall(function()
      deck.takeObject({
        index             = idx[i],
        position          = { dp.x, dp.y + 3, dp.z },
        smooth            = false,
        callback_function = function(o) pcall(function() o.destruct() end) end,
      })
    end)
    Wait.time(function() pull(i + 1) end, 0.1)
  end
  pull(1)
end

function rttRemoveFrogLeftovers()
  local gone = 0
  for _, o in ipairs(getAllObjects()) do
    pcall(function()
      local nm = o.name
      if (nm == "Card" or nm == "CardCustom") and (o.getDescription() or "") == "Frog" then
        o.destruct(); gone = gone + 1
      elseif nm == "Deck" then
        local frog, total = rttFrogCount(o)
        if total > 0 and frog == total then o.destruct(); gone = gone + 1 end
      end
    end)
  end
  return gone
end

RTT_FROG_TRIES = 6
RTT_FROG_WAIT  = 1.0

function rttShuffleFrogsIntoDeck(tries, after)
  tries = tries or 0
  local function merged() if after ~= nil then local f = after; after = nil; f() end end
  local holderOut, onSlot = false, nil
  pcall(function() holderOut = (getObjectFromGUID(RTT_HOLDER_GUID) ~= nil) end)
  pcall(function() onSlot = rttFindDrawDeck() end)
  if holderOut and onSlot == nil and tries < RTT_FROG_TRIES then
    Wait.time(function() rttShuffleFrogsIntoDeck(tries + 1) end, RTT_FROG_WAIT)
    merged()
    return
  end
  local mainDeck, frogObjs = rttFindMainDeck(), {}
  for _, o in ipairs(getAllObjects()) do
    local nm = o.name
    if nm == "Deck" and o ~= mainDeck then
      local frog, total = rttFrogCount(o)
      if total > 0 and frog == total then frogObjs[#frogObjs + 1] = o end
    elseif (nm == "Card" or nm == "CardCustom") and (o.getDescription() or "") == "Frog" then
      frogObjs[#frogObjs + 1] = o
    end
  end
  if mainDeck == nil then merged() return end
  for _, f in ipairs(frogObjs) do pcall(function() mainDeck.putObject(f) end) end
  Wait.time(function() if mainDeck ~= nil then pcall(function() mainDeck.shuffle() end) end end, 1.0)
  merged()
end

RTT_MAP_TAG       = "RTT Map"
RTT_MAP_NAME_TAG  = "RTT Map: "
RTT_MAP_5P_TAG    = "RTT Map 5P"
RTT_MAP_MIN_SNAPS = 40

function rttTagMap(board, name, fivep)
  if board == nil then return end
  pcall(function()
    local tags = {}
    for _, t in ipairs(board.getTags() or {}) do
      if t ~= RTT_MAP_TAG and t ~= RTT_MAP_5P_TAG
         and string.sub(t, 1, #RTT_MAP_NAME_TAG) ~= RTT_MAP_NAME_TAG then tags[#tags + 1] = t end
    end
    tags[#tags + 1] = RTT_MAP_TAG
    if name ~= nil and name ~= "" then tags[#tags + 1] = RTT_MAP_NAME_TAG .. name end
    if fivep == true then tags[#tags + 1] = RTT_MAP_5P_TAG end
    board.setTags(tags)
  end)
  pcall(rttTellSheet)
end

function rttMap()
  local board = nil
  pcall(function() board = (getObjectsWithTag(RTT_MAP_TAG) or {})[1] end)
  if board == nil then
    local cand, n = rttMapBoardTagged(), 0
    pcall(function() n = #(cand.getSnapPoints() or {}) end)
    if cand == nil or n < RTT_MAP_MIN_SNAPS then return nil, nil, false end
    rttTagMap(cand, RTT_CURRENT_MAP, RTT_MARSH_5P_BUILT == true)
    board = cand
  end
  local name, fivep = nil, false
  pcall(function()
    for _, t in ipairs(board.getTags() or {}) do
      if t == RTT_MAP_5P_TAG then fivep = true
      elseif string.sub(t, 1, #RTT_MAP_NAME_TAG) == RTT_MAP_NAME_TAG then
        name = string.sub(t, #RTT_MAP_NAME_TAG + 1)
      end
    end
  end)
  return board, name, fivep
end

function rttMapBoardTagged()
  local best, bestN = nil, 0
  for _, o in ipairs(getObjectsWithTag("Map Object")) do
    local ok, sp = pcall(function() return o.getSnapPoints() end)
    if ok and sp and #sp > bestN then best, bestN = o, #sp end
  end
  return best
end

function rttNameOf(o)
  local n = ""
  pcall(function()
    if o == nil then return end
    if o.isDestroyed ~= nil and o.isDestroyed() == true then return end
    n = o.getName() or ""
  end)
  return n
end

function rttFindBag(nick)
  if nick == nil or nick == "" then return nil end
  local hit = nil
  pcall(function() hit = (getObjectsWithTag("RTT Bag: " .. nick) or {})[1] end)
  if hit ~= nil then return hit end
  for _, o in ipairs(getAllObjects()) do
    if rttNameOf(o) == nick then return o end
  end
  return nil
end

function rttFindMapObject()
  local board = rttMap()
  return board
end

RTT_MAP_LOCK_SECS = 1
RTT_MAP_LOCK_GUID = nil

function rttHoldPrisoners()
  for guid in pairs(RTT_LAID or {}) do
    pcall(function()
      local o = getObjectFromGUID(guid)
      if o == nil then RTT_LAID[guid] = nil RTT_MARKING[guid] = nil return end
      if RTT_MARKING[guid] then return end
      local rec = RTT_LAID[guid]
      if rec.n ~= nil and rttNameOf(o) ~= rec.n then RTT_LAID[guid] = nil return end
      if o.getLock() ~= true then o.setLock(true) end
      if o.interactable ~= false then o.interactable = false end
    end)
  end
end

RTT_TABLE_HELD = false
function rttHoldTable()
  if RTT_TABLE_HELD then return end
  local n = 0
  pcall(function()
    for _, o in ipairs(getObjectsWithTag("Table Piece") or {}) do
      pcall(function()
        if o.getLock() ~= true then o.setLock(true) end
        if o.interactable ~= false then o.interactable = false end
      end)
      n = n + 1
    end
  end)
  if n > 0 then RTT_TABLE_HELD = true end
end

function rttHoldMapLocked()
  rttHoldTable()
  if RTT_RESYNCING == true then return end
  local m = nil
  if RTT_MAP_LOCK_GUID ~= nil then pcall(function() m = getObjectFromGUID(RTT_MAP_LOCK_GUID) end) end
  if m ~= nil then
    local isMap = false
    pcall(function() isMap = (m.hasTag(RTT_MAP_TAG) == true) end)
    if not isMap then m = nil; RTT_MAP_LOCK_GUID = nil end
  end
  if m == nil then
    pcall(function()
      m = rttMap()
      RTT_MAP_LOCK_GUID = (m ~= nil) and m.getGUID() or nil
    end)
  end
  if m == nil then return end
  pcall(function() if m.getLock() ~= true then m.setLock(true) end end)
  pcall(function() if m.interactable ~= false then m.interactable = false end end)
end

function rttForestWorldCenters(mapId)
  local cents = RTT_FOREST_UV[mapId]
  if cents == nil then return {} end
  local m = rttFindMapObject()
  if m == nil then return {} end
  local b = m.getBounds()
  local a = math.rad(m.getRotation().y)
  local sx, sz = b.size.x, b.size.z
  local out = {}
  for _, uv in ipairs(cents) do
    local lx, lz = uv[1] * sx, uv[2] * sz
    out[#out + 1] = {
      b.center.x + lx * math.cos(a) - lz * math.sin(a),
      b.center.z + lx * math.sin(a) + lz * math.cos(a),
    }
  end
  return out
end

function rttGetCurrentMap() local _, name = rttMap() return name end

function rttGetMarshExcluded() return RTT_MARSH_EXCLUDED end

function rttBadgerRelics()
  local m, mapId = rttMap()
  if m == nil or mapId == nil then
    pcall(function()
      broadcastToAll("Keepers: there is no map on the table, so the relics stay in their bag. "
                     .. "Place the map first.", { 1, 0.6, 0.2 })
    end)
    return
  end
  local bag = rttFindBag("Relics")
  if bag == nil then return end
  local targets = {}
  local recorded = RTT_RELIC_POS[mapId]
  if recorded ~= nil then
    for _, lc in ipairs(recorded) do
      local w = m.positionToWorld({ lc[1], 0.05, lc[2] })
      targets[#targets + 1] = { w.x, w.z }
    end
  else
    targets = rttForestWorldCenters(mapId)
  end
  if #targets == 0 then return end

  local guids = {}
  pcall(function()
    for _, e in ipairs(bag.getObjects() or {}) do
      if e.guid ~= nil then guids[#guids + 1] = e.guid end
    end
  end)
  rttShuffleList(guids)

  local i = 0
  local function place()
    i = i + 1
    local c = targets[i]
    if c == nil then return end
    pcall(function()
      bag.takeObject({ guid = guids[i], position = { c[1], 12.0, c[2] }, rotation = { 0, 180, 0 },
        smooth = false,
        callback_function = function(o) pcall(function() o.addTag("RTT Faction") end) end })
    end)
    Wait.frames(place, 1)
  end
  place()
end

