function rttWhenMapReady(fn, tries)
  tries = tries or 60
  local n = 0
  local function tick()
    n = n + 1
    local ready = false
    pcall(function() ready = (rttMapBoardTagged() ~= nil) end)
    if ready or n >= tries then pcall(fn) return end
    Wait.frames(tick, 3)
  end
  Wait.frames(tick, 1)
end

