function rttSeatFaction(color)
  if color == nil or color == "" then return nil end
  for _, s in ipairs(RTT_SEATS or {}) do
    if s ~= nil and s.color == color and s.faction ~= nil and s.faction ~= "" then return s.faction end
  end
  local hits = {}
  pcall(function()
    local raw = Global.getVar("RTT_SEAT_COLOR")
    if type(raw) ~= "string" or raw == "" then return end
    local dec = JSON.decode(raw)
    if type(dec) ~= "table" then return end
    for faction, seat in pairs(dec) do
      if seat == color then hits[#hits + 1] = faction end
    end
  end)
  if #hits == 1 then return hits[1] end
  return nil
end

local function rttPieceNamesFromDef(def)
  local supply, warrior, firstSupply = nil, nil, nil
  pcall(function()
    do
      if def ~= nil and def['data'] ~= nil then
        for _, v in ipairs(def['data']) do
          if warrior == nil then
            for nick in v.json:gmatch('"Nickname":%s*"([^"]*)"') do
              if warrior == nil and nick:match("Warrior$") then warrior = nick end
            end
          end
        end
        for _, v in ipairs(def['data']) do
          local nick = v.json:match('"Nickname":%s*"([^"]*)"')
          if nick ~= nil and nick:match("Supply$") then
            if firstSupply == nil then firstSupply = nick end
            if supply == nil and warrior ~= nil
               and v.json:find('"Nickname": "' .. warrior .. '"', 1, true) then
              supply = nick
            end
          end
        end
      end
    end
  end)
  return supply or firstSupply, warrior
end

function rttFactionPieceNames(faction)
  if faction == nil then return nil, nil end
  for _, cat in pairs(EVERYTHING) do
    if cat[faction] ~= nil then return rttPieceNamesFromDef(cat[faction]) end
  end
  return nil, nil
end

RTT_WARRIOR_SUPPLY = nil
local function rttFindByName(name)
  if name == nil or name == "" then return nil end
  for _, o in ipairs(getAllObjects()) do
    if rttNameOf(o) == name then return o end
  end
  return nil
end

RTT_BAG_OF = nil
function rttBagOfMap()
  if RTT_BAG_OF ~= nil then return RTT_BAG_OF end
  local m = {}
  local built = pcall(function()
    for _, cat in pairs(EVERYTHING) do
      for _, def in pairs(cat) do
        if type(def) == "table" and def['data'] ~= nil then
          for _, v in ipairs(def['data']) do
            local bag = v.json:match('"Name":%s*"[^"]*Bag[^"]*".-"Nickname":%s*"([^"]*)"')
                     or v.json:match('"Nickname":%s*"([^"]*Supply)"')
            if bag ~= nil and bag ~= "" then
              for nick in v.json:gmatch('"Nickname":%s*"([^"]*)"') do
                if nick ~= "" and nick ~= bag and m[nick] == nil then m[nick] = bag end
              end
            end
          end
        end
      end
    end
  end)
  if built and next(m) ~= nil then RTT_BAG_OF = m end
  return m
end

function rttIsWarrior(name)
  return tostring(name or ""):match("Warrior$") ~= nil
end

RTT_SUPPLY_OF = {}

function rttSupplyForPiece(name)
  if name == nil or name == "" then return nil end
  local memo = RTT_SUPPLY_OF[name]
  if memo ~= nil then
    if memo == false then return nil end
    return memo
  end

  local viaMap = nil
  pcall(function() viaMap = rttBagOfMap()[name] end)
  if viaMap ~= nil then RTT_SUPPLY_OF[name] = viaMap return viaMap end

  local found = nil
  if rttIsWarrior(name) then
    pcall(function()
      for _, cat in pairs(EVERYTHING or {}) do
        for _, def in pairs(cat) do
          if found == nil and type(def) == "table" and def['data'] ~= nil then
            local sup, war = rttPieceNamesFromDef(def)
            if war == name and sup ~= nil then found = sup end
          end
        end
      end
    end)
  end
  if found ~= nil then RTT_SUPPLY_OF[name] = found return found end

  pcall(function()
    for _, cat in pairs(EVERYTHING or {}) do
      for _, def in pairs(cat) do
        if found == nil and type(def) == "table" and def['data'] ~= nil then
          for _, v in ipairs(def['data']) do
            if found == nil and type(v.json) == "string"
               and string.find(v.json, '"Nickname": "' .. name .. '"', 1, true) ~= nil
               and (string.find(v.json, '"Name": "Custom_Model_Bag"', 1, true) ~= nil
                    or string.find(v.json, '"Name": "Bag"', 1, true) ~= nil
                    or string.find(v.json, '"Name": "Infinite_Bag"', 1, true) ~= nil) then
              local first = string.match(v.json, '"Nickname":%s*"([^"]*)"')
              if first ~= nil and first ~= "" and first ~= name then found = first end
            end
          end
        end
      end
    end
  end)

  local ready = false
  pcall(function() ready = (next(EVERYTHING or {}) ~= nil) end)
  if found ~= nil then RTT_SUPPLY_OF[name] = found
  elseif ready then RTT_SUPPLY_OF[name] = false end
  return found
end

RTT_WARRIOR_SUPPLY = nil
function rttWarriorSupplyMap()
  if RTT_WARRIOR_SUPPLY ~= nil then return RTT_WARRIOR_SUPPLY end
  local m = {}
  for nick, bag in pairs(rttBagOfMap()) do
    if nick:match("Warrior$") then m[nick] = bag end
  end
  if next(m) ~= nil then RTT_WARRIOR_SUPPLY = m end
  return m
end

