RTT_HOME_KEEP_FACING = { ["Plot"] = true }

RTT_HOME_KEEP_FACE = { ["Relic"] = true }
RTT_HOME_RETURN_SECS = 0.8
function rttHomeTurn(o, name, r)
  if RTT_HOME_KEEP_FACING[name] then return end
  local want = { r[1], r[2], r[3] }
  if RTT_HOME_KEEP_FACE[name] then
    local cur = nil
    pcall(function() cur = o.getRotation() end)
    if cur == nil then return end
    want = { cur.x, r[2], cur.z }
  end
  o.setRotation(want)
  if RTT_HOME_KEEP_FACE[name] then
    local guid = nil
    pcall(function() guid = o.getGUID() end)
    if guid == nil then return end
    Wait.time(function()
      local x = getObjectFromGUID(guid)
      if x == nil then return end
      pcall(function() if x.held_by_color == nil then x.setRotation(want) end end)
    end, RTT_HOME_RETURN_SECS)
  end
end

RTT_HOME_STACKED = { ["Acclaim"] = 2 }

RTT_HOME_NEVER = { ["RUIN"] = true }
function rttHomeNever(name)
  if name == nil or name == "" then return true end
  if RTT_HOME_NEVER[name] then return true end
  if name:match(" VP$") then return true end
  return false
end

RTT_SUPPLY_CHECK = 4
RTT_SUPPLY_DROP  = 3.0

RTT_HOME_LEFT_FIRST = { ["Relic"] = true }

RTT_HOME_FAMILY = { ["Waystation"] = true }

function rttHomeFamily(name)
  local last = tostring(name or ""):match("(%S+)%s*$")
  if last ~= nil and RTT_HOME_FAMILY[last] then return last end
  return name
end

function rttHomeMeasuredOnly(name)
  if RTT_HOME_EXTRA_ONLY[name] then return true end
  if rttIsWarrior(name) then return true end
  return rttBagOfMap()[name] ~= nil
end

function rttHomeSlots(name)
  local out = {}
  local onlyMeasured = rttHomeMeasuredOnly(name)
  for _, h in pairs(RTT_HOME or {}) do
    if h.n == name and (not onlyMeasured or h.x) then out[#out + 1] = h end
  end
  if #out == 0 then return out end
  return rttOrderSlots(out, name)
end

function rttOrderSlots(out, name)
  if #out > 2 then
    local near = {}
    for i, h in ipairs(out) do
      local best = nil
      for j, g in ipairs(out) do
        if i ~= j then
          local dx, dy, dz = h.p[1]-g.p[1], h.p[2]-g.p[2], h.p[3]-g.p[3]
          local d = dx*dx + dy*dy + dz*dz
          if best == nil or d < best then best = d end
        end
      end
      near[i] = math.sqrt(best or 0)
    end
    local sorted = {}
    for _, v in ipairs(near) do sorted[#sorted + 1] = v end
    table.sort(sorted)
    local med = sorted[math.max(1, math.ceil(#sorted / 2))]
    local keep = {}
    for i, h in ipairs(out) do
      if near[i] <= math.max(med * 4, 0.05) then keep[#keep + 1] = h end
    end
    if #keep > 0 then out = keep end
  end
  local sz = 0
  for _, h in ipairs(out) do sz = sz + h.p[3] end
  local s = (sz > 0) and -1 or 1
  local per = RTT_HOME_STACKED[name]
  local lf = RTT_HOME_LEFT_FIRST[name] and -1 or 1

  local function cluster(axis)
    local idx, order = {}, {}
    for i, h in ipairs(out) do order[i] = h end
    table.sort(order, function(a, b) return a.p[axis] < b.p[axis] end)
    local n, prev = 0, nil
    for _, h in ipairs(order) do
      if prev == nil or (h.p[axis] - prev) > 0.2 then n = n + 1 end
      idx[h] = n
      prev = h.p[axis]
    end
    return idx
  end
  local colOf, rowOf = cluster(1), cluster(3)

  table.sort(out, function(a, b)
    if per ~= nil then
      if rowOf[a] ~= rowOf[b] then return rowOf[a] * s < rowOf[b] * s end
      if colOf[a] ~= colOf[b] then return colOf[a] * s > colOf[b] * s end
      return a.p[2] < b.p[2]
    end
    if colOf[a] ~= colOf[b] then return colOf[a] * s * lf > colOf[b] * s * lf end
    if rowOf[a] ~= rowOf[b] then return rowOf[a] * s < rowOf[b] * s end
    return a.p[2] < b.p[2]
  end)
  return out
end

function rttHomeFamilySlots(fam)
  local out = {}
  for _, h in pairs(RTT_HOME or {}) do
    if rttHomeFamily(h.n) == fam and (h.x or not rttHomeMeasuredOnly(h.n)) then
      out[#out + 1] = h
    end
  end
  if #out == 0 then return out end
  return rttOrderSlots(out, fam)
end

function rttSlotsFor(name)
  local fam = rttHomeFamily(name)
  if fam == name then return rttHomeSlots(name) end
  return rttHomeFamilySlots(fam)
end

function rttHomeSlotTaken(slot, name, ignore, ytol)
  ytol = ytol or 0.6
  local fam = rttHomeFamily(name)
  local taken = false
  pcall(function()
    for _, o in ipairs(getAllObjects()) do
      if o ~= ignore and rttHomeFamily(rttNameOf(o)) == fam then
        local p = o.getPosition()
        local dx, dy, dz = p.x - slot.p[1], p.y - slot.p[2], p.z - slot.p[3]
        if dx * dx + dz * dz < 0.36 and math.abs(dy) < ytol then taken = true return end
      end
    end
  end)
  return taken
end

function rttHomeYTol(slots)
  local best = nil
  for i, a in ipairs(slots) do
    for j, b in ipairs(slots) do
      if i ~= j then
        local dx, dz = a.p[1] - b.p[1], a.p[3] - b.p[3]
        if dx * dx + dz * dz < 0.36 then
          local dy = math.abs(a.p[2] - b.p[2])
          if dy > 0.001 and (best == nil or dy < best) then best = dy end
        end
      end
    end
  end
  if best == nil then return 0.6 end
  return best * 0.45
end

function rttMyFaction(color)
  local who = rttPersonIn(color)
  local best, bestN = nil, -1
  for _, s in ipairs(RTT_SEATS or {}) do
    if s ~= nil and s.faction ~= nil and s.faction ~= "" and (s.pickedAt or 0) > bestN then
      local mine = (who ~= nil and s.owner == who) or (who == nil and s.picker == color)
      if mine then best, bestN = s.faction, s.pickedAt or 0 end
    end
  end
  if best ~= nil then return best end
  return rttSeatFaction(color)
end

function rttMySupplyBag(color)
  local faction = rttMyFaction(color)
  if faction ~= nil then
    local supName, warName = rttFactionPieceNames(faction)
    if supName == nil or warName == nil then
      return nil, "the " .. faction .. " has no warrior supply."
    end
    local bag = rttFindByName(supName)
    if bag ~= nil then return bag end
    return nil, "could not find the " .. supName .. " on the table."
  end

  if not rttHasHand(color) then return nil, "you are not seated at a hand." end
  local hp = nil
  pcall(function() hp = Player[color].getHandTransform(1).position end)
  if hp == nil then return nil, "you are not seated at a hand." end

  local known = {}
  for _, sup in pairs(rttWarriorSupplyMap()) do known[sup] = true end
  local best, bestd = nil, nil
  for _, o in ipairs(getAllObjects()) do
    if known[rttNameOf(o)] then
      local p = o.getPosition()
      local d = (p.x - hp.x) ^ 2 + (p.z - hp.z) ^ 2
      if bestd == nil or d < bestd then best, bestd = o, d end
    end
  end
  if best ~= nil and bestd <= 2500 then return best end
  if best ~= nil then return nil, "the nearest supply is not at your seat." end
  return nil, "no faction is seated in your colour."
end

function rttGizmoHome(color)
  local hovered = nil
  pcall(function() hovered = Player[color].getHoverObject() end)
  if hovered == nil then return end
  local name = hovered.getName() or ""
  if name == "" then return end

  local locked = false
  pcall(function() locked = (hovered.getLock() == true) end)
  if locked then
    return
  end

  if rttHomeNever(name) then return end

  local home = (RTT_HOME or {})[hovered.getGUID()]
  if RTT_HOME_OWN_SPOT[name] and home ~= nil then
    pcall(function()
      hovered.setPositionSmooth({ home.p[1], home.p[2], home.p[3] }, false, true)
      rttHomeTurn(hovered, name, home.r)
    end)
    return
  end

  local setSlots = rttSetSlotsFor(name)
  if #setSlots > 0 then
    local stol = rttHomeYTol(setSlots)
    for _, sl in ipairs(setSlots) do
      if not rttHomeSlotTaken(sl, name, hovered, stol) then
        pcall(function()
          hovered.setPositionSmooth({ sl.p[1], sl.p[2], sl.p[3] }, false, true)
          rttHomeTurn(hovered, name, sl.r)
        end)
        return
      end
    end
  end

  local slots = rttSlotsFor(name)

  if #slots > 0 then
    local kind = rttRelicKind(hovered)
    if kind ~= nil then
      local only = {}
      for _, sl in ipairs(slots) do if sl.k == kind then only[#only + 1] = sl end end
      if #only > 0 then slots = only end
    end
  end

  local ytol = rttHomeYTol(slots)
  for _, sl in ipairs(slots) do
    if not rttHomeSlotTaken(sl, name, hovered, ytol) then
      pcall(function()
        hovered.setPositionSmooth({ sl.p[1], sl.p[2], sl.p[3] }, false, true)
        rttHomeTurn(hovered, name, sl.r)
      end)
      return
    end
  end

  local bagName = rttSupplyForPiece(name)
  if bagName ~= nil then
    local bag = rttFindByName(bagName)
    if bag ~= nil then
      local g, bg = nil, nil
      pcall(function() g = hovered.getGUID() bg = bag.getGUID() end)
      pcall(function() bag.putObject(hovered) end)
      if g ~= nil and bg ~= nil then
        Wait.frames(function()
          local o, b = getObjectFromGUID(g), getObjectFromGUID(bg)
          if o == nil or b == nil then return end
          pcall(function()
            local p = b.getPosition()
            o.setPositionSmooth({ p.x, p.y + RTT_SUPPLY_DROP, p.z }, false, true)
          end)
        end, RTT_SUPPLY_CHECK)
      end
      return
    end
    pcall(function()
      broadcastToColor("The " .. tostring(bagName) .. " is not on the table.", color,
                       { r = 1, g = 0.6, b = 0.2 })
    end)
    return
  end

  if rttIsWarrior(name) then return end

  if home ~= nil then
    pcall(function()
      hovered.setPositionSmooth({ home.p[1], home.p[2], home.p[3] }, false, true)
      hovered.setRotation({ home.r[1], home.r[2], home.r[3] })
    end)
  end
end

function rttGizmoTake(color)
  if rttPointerOverDeckArea(color) then return end
  local pos = nil
  pcall(function() pos = Player[color].getPointerPosition() end)
  local faction = rttMyFaction(color)
  if faction ~= nil and pos ~= nil then
    local _, warName = rttFactionPieceNames(faction)
    if warName ~= nil then
      local slots = rttSetSlotsFor(warName)
      local ytol = rttHomeYTol(slots)
      for i = #slots, 1, -1 do
        local o = rttPieceOnSlot(slots[i], warName, ytol)
        local locked = false
        if o ~= nil then pcall(function() locked = (o.getLock() == true) end) end
        if o ~= nil and not locked then
          pcall(function() o.setPositionSmooth({ pos.x, pos.y + 1.5, pos.z }, false, true) end)
          return
        end
      end
    end
  end
  local bag, why = rttMySupplyBag(color)
  if bag == nil then
    broadcastToColor((why or "Could not tell which supply is yours."), color,
                     { r = 1, g = 0.6, b = 0.2 })
    return
  end
  local n = 0
  pcall(function() n = bag.getQuantity() end)
  if n <= 0 then
    broadcastToColor("The supply is empty.", color, { r = 1, g = 0.6, b = 0.2 })
    return
  end
  local pos = nil
  pcall(function() pos = Player[color].getPointerPosition() end)
  local bp = bag.getPosition()
  if pos == nil then pos = { x = bp.x, y = bp.y + 2, z = bp.z }
  else pos = { x = pos.x, y = pos.y + 1.5, z = pos.z } end
  local ry = 0
  pcall(function() ry = bag.getRotation().y or 0 end)
  pcall(function()
    bag.takeObject({
      position = { bp.x, bp.y + 1.2, bp.z }, rotation = { 0, ry, 0 }, smooth = false,
      callback_function = function(o)
        pcall(function() o.addTag("RTT Faction") end)
        pcall(function() o.setPositionSmooth(pos, false, true) end)
      end
    })
  end)
end

RTT_DISC_TAG = "RTT Laid Disc"
RTT_GLOW_RGB = { r = 0, g = 0, b = 0 }
RTT_PRISONER_FADE = 0.48

RTT_PRISONER_OVER = 1.0 + RTT_PRISONER_FADE

function rttFaded(c)
  if c == nil then return nil end
  local k = RTT_PRISONER_FADE
  local r = (c.r ~= nil) and c.r or c[1]
  local g = (c.g ~= nil) and c.g or c[2]
  local b = (c.b ~= nil) and c.b or c[3]
  if r == nil or g == nil or b == nil then return nil end
  if r >= 1 and g >= 1 and b >= 1 then
    local o = RTT_PRISONER_OVER
    return { r * o, g * o, b * o }
  end
  return { r + (1 - r) * k, g + (1 - g) * k, b + (1 - b) * k }
end
RTT_PLAYER_RGB = {
  White  = { 1, 1, 1 },              Brown  = { 0.443, 0.231, 0.09 },
  Red    = { 0.856, 0.1, 0.094 },    Orange = { 0.956, 0.392, 0.113 },
  Yellow = { 0.905, 0.898, 0.172 },  Green  = { 0.192, 0.701, 0.168 },
  Teal   = { 0.129, 0.694, 0.607 },  Blue   = { 0.118, 0.53, 1 },
  Purple = { 0.627, 0.125, 0.941 },  Pink   = { 0.96, 0.439, 0.807 },
  Grey   = { 0.5, 0.5, 0.5 },        Black  = { 0.25, 0.25, 0.25 },
}
RTT_LAID = {}
RTT_PRISONER_REACH = 1.2

RTT_MARKING = {}

function rttIsLaid(o)
  if o == nil then return false end
  local guid = nil
  pcall(function() guid = o.getGUID() end)
  return guid ~= nil and RTT_LAID[guid] ~= nil
end

function rttGizmoLay(color) rttGizmoMark(color) end
function rttGizmoGlow(color) rttGizmoMark(color) end

function rttFreePrisoner(o, guid, standUp)
  local was = RTT_LAID[guid]
  if was == nil then return end
  RTT_LAID[guid] = nil
  pcall(function() o.setLock(false) end)
  pcall(function() o.interactable = true end)
  if standUp ~= false then
    pcall(function()
      local ry = o.getRotation().y
      o.setRotation({ was.rot[1], ry, was.rot[3] })
      if was.pos ~= nil then o.setPosition({ was.pos[1], was.pos[2], was.pos[3] }) end
    end)
  end
  if was.disc ~= nil then
    pcall(function()
      local x = getObjectFromGUID(was.disc)
      if x ~= nil then x.destruct() end
    end)
  end
  pcall(function() o.highlightOff() end)
  if was.tint ~= nil then
    pcall(function() o.setColorTint({ was.tint[1], was.tint[2], was.tint[3] }) end)
  end
end

function rttGizmoMark(color)
  local hovered = nil
  pcall(function() hovered = Player[color].getHoverObject() end)
  local name = ""
  pcall(function() name = (hovered ~= nil and hovered.getName()) or "" end)

  if not name:match("Warrior$") then
    local pp = nil
    pcall(function() pp = Player[color].getPointerPosition() end)
    if pp ~= nil then
      local best, bestd = nil, RTT_PRISONER_REACH * RTT_PRISONER_REACH
      for g, rec in pairs(RTT_LAID or {}) do
        if not RTT_MARKING[g] and type(rec) == "table" and rec.pos ~= nil then
          local dx, dz = (pp.x or 0) - rec.pos[1], (pp.z or 0) - rec.pos[3]
          local d = dx * dx + dz * dz
          if d < bestd then best, bestd = g, d end
        end
      end
      if best ~= nil then
        local o = getObjectFromGUID(best)
        if o ~= nil then pcall(function() rttFreePrisoner(o, best) end) else RTT_LAID[best] = nil end
      end
    end
    return
  end

  local guid = nil
  pcall(function() guid = hovered.getGUID() end)
  if guid == nil then return end

  if RTT_MARKING[guid] then return end

  local laidRec = RTT_LAID[guid]
  if laidRec ~= nil then
    if laidRec.n == nil or laidRec.n == name then
      pcall(function() rttFreePrisoner(hovered, guid) end)
      return
    end
    RTT_LAID[guid] = nil
  end

  local r, p, b = nil, nil, nil
  pcall(function() r = hovered.getRotation() end)
  pcall(function() p = hovered.getPosition() end)
  pcall(function() b = hovered.getBounds() end)
  if r == nil or p == nil then return end
  local foot = nil
  if b ~= nil and b.center ~= nil and b.size ~= nil then foot = b.center.y - b.size.y / 2 end
  local tint = nil
  pcall(function() tint = hovered.getColorTint() end)
  local rx = r.x
  local nx = ((rx % 360) + 360) % 360
  if nx > 45 and nx < 315 then rx = 0 end
  RTT_LAID[guid] = { rot = { rx, r.y, r.z }, pos = { p.x, p.y, p.z }, who = color, n = name,
                     tint = (tint ~= nil) and { tint.r, tint.g, tint.b } or nil }
  RTT_MARKING[guid] = true
  pcall(function() hovered.setRotation({ 90, r.y, r.z }) end)
  Wait.frames(function()
    local hovered = getObjectFromGUID(guid)
    if hovered == nil then RTT_MARKING[guid] = nil return end
    local same = false
    pcall(function() same = (RTT_LAID[guid] ~= nil) and ((hovered.getName() or "") == name) end)
    if not same then RTT_MARKING[guid] = nil return end
    local rest = nil
    pcall(function()
      local np = hovered.getPosition()
      rest = np.y
      if foot ~= nil then
        local nb = hovered.getBounds()
        rest = np.y + (foot - (nb.center.y - nb.size.y / 2)) + 0.03
        hovered.setPosition({ np.x, rest, np.z })
      end
    end)
    pcall(function() hovered.setLock(true) end)
    pcall(function() hovered.interactable = false end)
    pcall(function() hovered.highlightOn(RTT_GLOW_RGB) end)
    pcall(function()
      local faded = rttFaded(hovered.getColorTint())
      if faded ~= nil then hovered.setColorTint(faded) end
    end)
    RTT_MARKING[guid] = nil
  end, 2)
end

function rttGizmoWarrior(color) rttGizmoTake(color) end

RTT_TOKEN_PICK = {}
RTT_KEY2 = {}

RTT_KEY2_HOLD = 1

function rttTokenEligible(name)
  if name == nil or name == "" then return false end
  if string.find(name, "Warrior", 1, true) ~= nil then return false end
  if rttSupplyForPiece(name) ~= nil then return true end
  return #rttSlotsFor(name) > 0
end

function rttPieceOnSlot(slot, name, ytol)
  ytol = ytol or 0.6
  local found = nil
  pcall(function()
    for _, o in ipairs(getAllObjects()) do
      if rttNameOf(o) == name then
        local p = o.getPosition()
        local dx, dy, dz = p.x - slot.p[1], p.y - slot.p[2], p.z - slot.p[3]
        if dx * dx + dz * dz < 0.36 and math.abs(dy) < ytol then found = o return end
      end
    end
  end)
  return found
end

function rttGizmoToken(color)
  local name = RTT_TOKEN_PICK[color]
  if name == nil or name == "" then return end
  local pos = nil
  pcall(function() pos = Player[color].getPointerPosition() end)
  if pos == nil then return end
  local to = { pos.x, pos.y + 1.5, pos.z }

  local setSlots = rttSetSlotsFor(name)
  local stol = rttHomeYTol(setSlots)
  for i = #setSlots, 1, -1 do
    local o = rttPieceOnSlot(setSlots[i], name, stol)
    if o ~= nil then
      pcall(function() o.setPositionSmooth(to, false, true) end)
      return
    end
  end

  local slots = rttSlotsFor(name)
  local ytol = rttHomeYTol(slots)
  for i = #slots, 1, -1 do
    local o = rttPieceOnSlot(slots[i], name, ytol)
    if o ~= nil then
      pcall(function() o.setPositionSmooth(to, false, true) end)
      return
    end
  end

  local bag = rttFindByName(rttSupplyForPiece(name))
  if bag ~= nil then
    local n = 0
    pcall(function() n = bag.getQuantity() end)
    if n > 0 then
      local bp = bag.getPosition()
      local ry = 0
      pcall(function() ry = bag.getRotation().y or 0 end)
      pcall(function()
        bag.takeObject({
          position = { bp.x, bp.y + 1.2, bp.z }, rotation = { 0, ry, 0 }, smooth = false,
          callback_function = function(o)
            pcall(function() o.addTag("RTT Faction") end)
            pcall(function() o.setPositionSmooth(to, false, true) end)
          end
        })
      end)
      return
    end
  end

  pcall(function()
    broadcastToColor("No " .. tostring(name) .. " left to hand out.", color,
                     { r = 1, g = 0.6, b = 0.2 })
  end)
end

RTT_KEY4 = {}
RTT_KEY4_HOLD = 1
RTT_HOME_SET = {}
function rttSetSlotsFor(name)
  local out = {}
  for _, sp in ipairs((RTT_HOME_SET or {})[name] or {}) do
    if type(sp) == "table" and sp.p ~= nil then
      out[#out + 1] = { n = name, f = "", p = sp.p, r = sp.r or { 0, 0, 0 }, set = true }
    end
  end
  if #out == 0 then return out end
  return rttOrderSlots(out, name)
end
function rttSetHomes(color)
  local picked = {}
  pcall(function() picked = Player[color].getSelectedObjects() or {} end)
  if #picked == 0 then
    local hov = nil
    pcall(function() hov = Player[color].getHoverObject() end)
    if hov ~= nil then picked = { hov } end
  end
  local rows, n = {}, 0
  for _, o in ipairs(picked) do
    pcall(function()
      local name = o.getName() or ""
      if rttHomeNever(name) then return end
      local p, r = o.getPosition(), o.getRotation()
      rows[name] = rows[name] or {}
      table.insert(rows[name], { p = { p.x, p.y, p.z }, r = { r.x, r.y, r.z } })
      n = n + 1
    end)
  end
  if n == 0 then
    pcall(function()
      broadcastToColor("Numpad 4: select the pieces first, then hold it a second.", color, { r = 1, g = 0.6, b = 0.2 })
    end)
    return
  end
  local list = {}
  for name, row in pairs(rows) do
    RTT_HOME_SET[name] = row
    list[#list + 1] = name
  end
  table.sort(list)
  pcall(function()
    broadcastToColor("Home set for " .. n .. " piece(s): " .. table.concat(list, ", ") .. ".", color,
                     { r = 0.7, g = 1, b = 0.7 })
  end)
end
function rttKey4Down(color)
  local st = { set = false }
  RTT_KEY4[color] = st
  st.id = Wait.time(function()
    if RTT_KEY4[color] ~= st then return end
    st.set = true
    pcall(function() rttSetHomes(color) end)
  end, RTT_KEY4_HOLD)
end
function rttKey4Up(color)
  local st = RTT_KEY4[color]
  RTT_KEY4[color] = nil
  if st == nil then return end
  if st.id ~= nil and not st.set then pcall(function() Wait.stop(st.id) end) end
end

function rttKey2Down(color)
  if rttPointerOverDeckArea(color) then return end
  local hovered = nil
  pcall(function() hovered = Player[color].getHoverObject() end)
  local name = ""
  if hovered ~= nil then name = hovered.getName() or "" end
  local st = { set = false }
  RTT_KEY2[color] = st
  if rttTokenEligible(name) then
    st.id = Wait.time(function()
      if RTT_KEY2[color] ~= st then return end
      st.set = true
      RTT_TOKEN_PICK[color] = name
      pcall(function()
        broadcastToColor("Numpad 2 now hands you a " .. name .. ".", color,
                         { r = 0.7, g = 1, b = 0.7 })
      end)
    end, RTT_KEY2_HOLD)
  end
end

function rttKey2Up(color)
  local st = RTT_KEY2[color]
  RTT_KEY2[color] = nil
  if st == nil then return end
  if st.id ~= nil then pcall(function() Wait.stop(st.id) end) end
  if st.set then return end
  pcall(function() rttGizmoToken(color) end)
end

RTT_DECK_AREA_PAD = 1.0

function rttPointerOverDeckArea(color)
  local hovered, pos = nil, nil
  pcall(function() hovered = Player[color].getHoverObject() end)
  pcall(function() pos = Player[color].getPointerPosition() end)
  if hovered ~= nil then
    local onArea = false
    pcall(function() onArea = (hovered.hasTag("Deck Object") or hovered.hasTag("RTT Pond")) end)
    if onArea then return true end
    local tag, name = nil, nil
    pcall(function() tag = hovered.tag end)
    pcall(function() name = hovered.name end)
    if tag == "Deck" or name == "Deck" or name == "DeckCustom" then
      pcall(function() pos = hovered.getPosition() end)
    end
  end
  if pos == nil then return false end
  local areas = {}
  pcall(function() areas[#areas + 1] = getObjectFromGUID(RTT_HOLDER_GUID) end)
  pcall(function() for _, o in ipairs(getObjectsWithTag("RTT Pond") or {}) do areas[#areas + 1] = o end end)
  for _, o in ipairs(areas) do
    local inside = false
    pcall(function()
      if o == nil then return end
      local b = o.getBounds()
      inside = math.abs(pos.x - b.center.x) <= b.size.x / 2 + RTT_DECK_AREA_PAD
           and math.abs(pos.z - b.center.z) <= b.size.z / 2 + RTT_DECK_AREA_PAD
    end)
    if inside then return true end
  end
  return false
end

function onScriptingButtonDown(idx, color)
  if     idx == 10 then pcall(function() rttGizmoHome(color) end)
  elseif idx == 1  then pcall(function() rttGizmoTake(color) end)
  elseif idx == 2  then pcall(function() rttKey2Down(color) end)
  elseif idx == 3  then pcall(function() rttGizmoMark(color) end)
  elseif idx == 4  then pcall(function() rttKey4Down(color) end)
  elseif idx == 9  then pcall(function() rttLiveKey(color) end)
  end
end

function onScriptingButtonUp(idx, color)
  if idx == 2 then pcall(function() rttKey2Up(color) end) end
  if idx == 4 then pcall(function() rttKey4Up(color) end) end
end
